     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'frisee fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Frisée fraîche', 200, 'g', 'required',
     'salade', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. On part de deux cuisses confites telles qu''on les achète, environ 180 g pièce avec l''os et leur couche de graisse : elles rendront les 200 g de chair comestible portés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher les cuisses peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que les cuisses se manipulent, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Trier la frisée en ne gardant que le cœur blond et les feuilles tendres, écarter les grandes côtes vertes trop amères, laver à grande eau froide et essorer sans ménagement. Une feuille encore humide repousse la vinaigrette au lieu de la retenir, et le lit se retrouve à la fois fade et détrempé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dans un autre bol, délayer la moutarde avec le vinaigre, une pincée de sel et un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Assaisonner la frisée d''un tiers de la vinaigrette et la retourner à la main, sans la brasser, puis en dresser un lit souple au centre de chaque assiette. Répartir la pulpe de tomate égouttée autour, poser dessus la chair de canard encore tiède et les éclats de peau, napper du reste de vinaigrette au tout dernier moment et porter à table aussitôt : la frisée s''affaisse en quelques minutes sous le gras tiède, et le contraste tiède contre frais s''efface avec elle.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D1', 'recipe_family', 'Salade landaise à la frisée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('538f3305b27d79f464effe173451b931'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["gras de canard confit","acidité vinaigrée","moutarde"],"aroma_families":["rôti","végétal frais","acidulé"],"target_textures":["peau de canard croustillante","chair effilochée fondante","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.","Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise aux pignons et à l''échalote', 'salade landaise aux pignons et a l echalote', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise aux pignons et à l''échalote', 'Salade au confit de canard avec pignons de pin torréfiés et échalotes en vinaigrette', ds.id, 'SRC-054-D2',
    'Myko', 'editorial', 4, 20, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a383452a2dcb1eed177e2715289375f1',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','végétal frais','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.','Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion','torréfaction']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites','fruits à coque']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, vinaigrette une semaine au réfrigérateur en bocal fermé, pulpe de tomate le jour même. Une fois assaisonnée, la salade s''affaisse en moins d''une heure. Ne se congèle pas : la tomate râpée rend toute son eau à la décongélation et la peau croustillante devient molle ; seul le confit non désossé supporte le congélateur, trois mois sous graisse.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Parsemer de pignons torréfiés à sec et glisser une échalote ciselée dans la vinaigrette.","rationale":"Deux ajouts modestes qui travaillent chacun à un bout du plat : quarante grammes de pignons torréfiés opposent un croquant sec à la chair effilochée, et trente grammes d''échalote fondus dans le vinaigre donnent à la sauce un mordant aromatique que la moutarde seule ne fournit pas. L''échalote demande un temps de dégorgement dans le vinaigre, sans quoi elle reste agressive et remonte longtemps après le repas. Les pignons introduisent l''allergène fruits à coque dans une recette qui n''en portait aucun, et perdent leur croquant dès qu''ils touchent la vinaigrette : ils se sèment au tout dernier geste.","operations":[{"op":"add","form":"Pignon de pin","quantity":40,"unit":"g","role":"garniture croquante","optional":false},{"op":"add","form":"Échalote crue","quantity":30,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"insert","after":4,"instruction":"Verser les pignons de pin dans une petite poêle froide, sans matière grasse, et les faire blondir à feu moyen environ trois minutes en les remuant sans cesse. Les débarrasser dans une assiette froide dès qu''ils sentent la résine : leur propre huile les fait passer du doré à l''amer en quelques secondes de trop, et la poêle chaude continue de les cuire hors du feu."},{"op":"replace","n":6,"instruction":"Éplucher l''échalote et la ciseler le plus finement possible, puis la laisser dégorger cinq minutes dans le vinaigre avec une pincée de sel prise sur les 3 g : l''acide mange son mordant et elle ne remontera plus en bouche longtemps après le repas. Délayer ensuite la moutarde dans ce vinaigre parfumé, donner un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, parsemer des pignons torréfiés, napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : les pignons perdent leur croquant dès qu''ils trempent dans la sauce, et le contraste tiède contre frais s''efface en quelques minutes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
