    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soufflé au comté', 'Soufflé à la béchamel de gruyère et comté affiné pour une saveur plus prononcée', ds.id, 'SRC-056-D2',
    'Myko', 'editorial', 4, 20, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '01cbb4f7921e9d23be9fa503819c9cdf',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":5,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['comté affiné','noisette','beurre','jaune d''œuf']::text[],
    ARRAY['lactée','beurrée','épicée douce']::text[], ARRAY['mousseux','aérien','croûte dorée','cœur crémeux']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Comté']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, ici comté et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.','Le comté s''incorpore hors du feu dans une base tiède : fondu à chaud, il se sépare et laisse un appareil huileux que les blancs ne rattrapent plus.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-056'), '{"variant_label":"Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.","rationale":"L''emmental cède toute sa place au comté, à poids égal : le soufflé gagne une profondeur de noisette et de croûte, un salé fruité que l''emmental n''a jamais eu, et perd la douceur neutre qui le rendait consensuel. Le comté est plus salé et plus gras, il faut donc saler la base d''une main encore plus légère et accepter un appareil un peu plus lourd à monter. Il fond aussi moins docilement : versé dans une béchamel bouillante il rend son gras et grumelle au lieu de se fondre. La seconde branche de la variante, celle de la mimolette vieille, n''est pas écrite ici faute de forme au catalogue.","operations":[{"op":"substitute","form":"Emmental râpé","with":"Comté","quantity":105,"unit":"g","role":"fromage"}],"steps":[{"op":"replace","n":6,"instruction":"Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Verser ensuite le comté et le gruyère râpé restant en plusieurs fois, hors du feu et sur une base seulement tiède : jeté dans une béchamel encore bouillante, un fromage aussi gras rend son huile et grumelle au lieu de fondre. Râper la muscade moulue, poivrer, et saler d''une main plus légère encore que d''ordinaire, le comté apportant déjà son propre sel."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

