  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soufflé au fromage et à la ciboulette', 'Soufflé au gruyère et emmental relevé de ciboulette fraîche', ds.id, 'SRC-056-D3',
    'Myko', 'editorial', 4, 20, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '5839718ea88fa4b896a8c110df766f8f',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['fromage affiné','ciboulette','beurre']::text[],
    ARRAY['lactée','beurrée','alliacée fraîche']::text[], ARRAY['mousseux','aérien','croûte dorée piquée de vert','cœur crémeux']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Emmental râpé']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.','La ciboulette reste une trace et non un ingrédient de poids : au-delà d''une cuillerée, l''appareil s''alourdit et le soufflé cesse de monter droit.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-056'), '{"variant_label":"Soufflé aux herbes : une cuillerée de ciboulette ou d''estragon ciselé ajoutée aux jaunes, sans jamais dépasser cette dose sous peine d''alourdir l''appareil.","rationale":"Huit grammes de ciboulette ciselée, soit la cuillerée de la variante et pas un brin de plus : son rôle est de tendre un fil vert et allié à travers le gras du fromage, non de parfumer franchement. Ce qu''elle coûte est double — elle apporte de l''eau et un peu de matière à un appareil dont toute la tenue repose sur la légèreté, et sa couleur passe au vert olive éteint sous les trente-cinq minutes de four. Doubler la dose se voit immédiatement : la levée est plus basse et la croûte se piquette de points brunis.","operations":[{"op":"add","form":"Ciboulette fraîche","quantity":8,"unit":"g","role":"herbe","optional":false}],"steps":[{"op":"replace","n":6,"instruction":"Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Ciseler la ciboulette fraîche au couteau bien aiguisé, en coupant net plutôt qu''en hachant : écrasée, elle noircit et rend une eau verte qui strie la base. L''ajouter à ce moment précis, dans un appareil encore tiède dont la chaleur libère le parfum sans le cuire. Verser ensuite l''emmental râpé et le gruyère râpé restant en plusieurs fois, hors du feu, jusqu''à obtenir une base lisse et brillante, puis râper la muscade moulue, poivrer et saler d''une main légère seulement."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

