     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'miel' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Miel', 25, 'g', 'required',
     'caramélisation', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 270 g d''oignons entiers, c''est-à-dire trois beaux oignons tels qu''on les achète : une fois pelés et parés, il en reste les 240 g de chair nette utilisés ici. Les couper en deux dans la hauteur puis les émincer en demi-lunes fines et régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une large sauteuse, y jeter les oignons avec le miel et une petite pincée de sel, couvrir et laisser suer huit minutes à feu doux, le temps qu''ils rendent leur eau et s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer le couvercle, ajouter les lardons et poursuivre vingt-cinq minutes à feu moyen en remuant souvent, bien au-delà du blond : les oignons doivent s''affaisser en une confiture brune et brillante où le miel a fini de caraméliser et où plus une goutte d''eau ne subsiste. C''est la seule garantie de cette version — rien ne viendra plus retenir l''humidité, et une compotée encore mouillée détremperait le feuilletage par en dessous. Débarrasser dans un plat et laisser tiédir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter le four à 200 °C. Étaler la pâte avec son papier au fond d''un moule de vingt-six centimètres, piquer le fond à la fourchette et plaquer les bords contre la paroi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler la compotée tiède sur le fond de pâte en couche mince et régulière, en laissant deux centimètres de bord nus, puis enfourner vingt-cinq minutes. La garniture n''a plus rien à faire prendre : c''est le feuilletage qui commande la cuisson, et il est cuit quand ses bords sont montés, franchement dorés et secs au toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Sortir la tarte et la laisser reposer cinq minutes sur une grille. Elle se mange tiède et jamais brûlante : c''est en retombant un peu que le sucre caramélisé cesse de couler et que la douceur de l''oignon se lit vraiment. La détailler en carrés plutôt qu''en parts, la couche est trop mince pour tenir sur une pointe.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-057-D4', 'recipe_family', 'Tarte fine à l''oignon confit au miel',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-057-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-057-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-057-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c4878df563408db1a3f77f64914d1e5b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":4,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":3},"dominant_flavors":["oignon confit caramélisé","miel","lard fumé"],"aroma_families":["allium confit","caramel","fumé"],"target_textures":["feuilletage sec et cassant","compotée dense et brillante"],"signature_ingredients":["Oignon jaune cru","Pâte feuilletée crue","Miel"],"identity_guardrails":["La compotée va ici jusqu''au brun brillant, bien au-delà du blond de la version courante : arrêtée trop tôt, elle rend son eau sur le feuilletage et la tarte fine devient molle.","Aucun appareil œuf-crème : c''est précisément ce que cette version supprime, et le remettre même en fine couche la ramène à la tarte à l''oignon ordinaire.","La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.","Le miel n''est plus un correcteur d''amertume mais la matière sucrée du plat : il doit caraméliser dans la compotée et non se verser en filet au dressage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Terrine de campagne au poulet', 'terrine de campagne au poulet', 'France', 'France',
     'meal', 'charcuterie', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Terrine de campagne au poulet', 'Terrine de porc haché et échine avec des morceaux de poulet intégrés dans la masse', ds.id, 'SRC-058-D1',
    'Myko', 'editorial', 8, 50, 120, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'acbb9ac7c88c73879c77eea1de81cd4e',
    '{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['porc gras','volaille saisie','poivre noir','eau-de-vie']::text[],
    ARRAY['herbacé','alliacé','boisé']::text[], ARRAY['farce grossière','lanières de volaille fermes','tranche en étages']::text[],
    ARRAY['Échine de porc crue','Poitrine de porc crue','Cognac']::text[], ARRAY['Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.','Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.','Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identité de charcuterie de garde.','Les lanières de poulet se rangent en étages et doivent se voir à la coupe : hachées avec le reste, elles ne feraient qu''appauvrir la farce en gras sans rien apporter à la tranche.']::text[],
    ARRAY['marinade','hachage','bain-marie','pressage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Repos obligatoire de 24 a 48 heures entre 0 et 4 degres avant la premiere tranche. Entiere et couverte de sa graisse figee, la terrine se garde 8 a 10 jours au refrigerateur ; une fois entamee, filmez la coupe au contact et consommez sous 4 jours. La congelation est possible en portions filmees jusqu''a 2 mois, mais elle detend la farce et rend la tranche plus friable a la decongelation, qui doit se faire une nuit au refrigerateur.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-058'), '{"variant_label":"Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.","rationale":"La moitié du porc haché cède la place à des lanières de blanc de poulet saisies puis montées en étages : la tranche se dessine en couches claires et la terrine s''allège nettement, le blanc n''apportant presque pas de gras. C''est justement ce qui la menace — la farce a moins de matière grasse à redistribuer, et un poulet déjà coloré à la poêle puis passé deux heures au bain-marie sèche vite dès que le cœur dépasse les 72 degrés. La texture se divise aussi : on quitte le grain homogène d''une campagne pour une alternance de farce grossière et de viande en morceaux, plus près d''une terrine montée que d''un pâté.","operations":[{"op":"scale","form":"Porc haché cru","factor":0.5},{"op":"add","form":"Blanc de poulet cru, sans peau","quantity":250,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"insert","after":4,"instruction":"Detaillez les blancs de poulet en lanieres d''un bon centimetre dans le sens de la longueur, salez-les legerement et colorez-les a feu vif dans une poele a peine huilee, une minute par face et pas davantage : il s''agit de leur fixer une croute doree et du gout, pas de les cuire, car ils passeront encore deux heures au bain-marie et un blanc cuit deux fois ressort cotonneux. Debarrassez-les sur une assiette froide et reservez au refrigerateur jusqu''au montage."},{"op":"replace","n":6,"instruction":"Incorporez le porc hache cru, les oeufs battus, la fondue d''aromates refroidie et le persil cisele, puis travaillez la farce a la main pendant deux a trois minutes, jusqu''a ce qu''elle devienne franchement collante et se decolle des parois en un seul bloc. Le porc hache est ici reduit de moitie et les lanieres de poulet prendront sa place en volume : une farce moins abondante doit etre d''autant mieux liee pour tenir autour d''elles et ne pas se fendre a la coupe."},{"op":"replace","n":8,"instruction":"Tassez un tiers de la farce au fond d''un moule a terrine d''environ 1,2 litre en chassant chaque poche d''air du poing, rangez dessus la moitie des lanieres de poulet bien a plat et tete-beche, couvrez d''un deuxieme tiers de farce, puis du reste des lanieres, et finissez par la farce restante. Disposez les lanieres perpendiculairement a la longueur du moule : c''est ainsi que la tranche montrera des etages nets plutot que des accidents. Lissez la surface en la bombant legerement, puis fermez avec le couvercle ou une double feuille d''aluminium bien serree."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

