  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faites vos courses en poids d''achat, pas en poids net : demandez 250 g de poitrine de porc avec sa couenne, qui ne laissera qu''environ 200 g de chair une fois paree, 300 g d''echine a desosser pour 275 g de viande, et 400 g de porc deja hache. Une tete d''ail fournit les 15 g de gousses epluchees, une petite botte de persil les 18 g de feuilles, deux gros oeufs les 100 g hors coquille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Otez la couenne, les cartilages et les esquilles de la poitrine, desossez l''echine, puis taillez les deux viandes en cubes de deux centimetres sans retirer le gras : c''est lui qui donnera sa tenue et son moelleux a la tranche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Reunissez les cubes dans un grand saladier avec le cognac, le sel fin, le poivre noir moulu et le thym seche, melangez a pleines mains, couvrez et laissez macerer deux heures au refrigerateur pour que l''assaisonnement penetre le muscle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, epluchez l''oignon jaune et les echalotes, hachez-les finement et faites-les fondre a feu doux dans une poele a peine huilee, sans les colorer ; ajoutez l''ail ecrase a la toute fin, debarrassez et laissez refroidir completement avant tout contact avec la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Detaillez les blancs de poulet en lanieres d''un bon centimetre dans le sens de la longueur, salez-les legerement et colorez-les a feu vif dans une poele a peine huilee, une minute par face et pas davantage : il s''agit de leur fixer une croute doree et du gout, pas de les cuire, car ils passeront encore deux heures au bain-marie et un blanc cuit deux fois ressort cotonneux. Debarrassez-les sur une assiette froide et reservez au refrigerateur jusqu''au montage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Passez la viande maceree au hachoir muni de la grille de 8 mm, puis repassez seulement un gros tiers du hachis a la grille fine : ce tiers apportera le liant, le reste doit rester franchement grossier, c''est la signature d''une campagne face a une mousse de foie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporez le porc hache cru, les oeufs battus, la fondue d''aromates refroidie et le persil cisele, puis travaillez la farce a la main pendant deux a trois minutes, jusqu''a ce qu''elle devienne franchement collante et se decolle des parois en un seul bloc. Le porc hache est ici reduit de moitie et les lanieres de poulet prendront sa place en volume : une farce moins abondante doit etre d''autant mieux liee pour tenir autour d''elles et ne pas se fendre a la coupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Poelez une petite boulette de farce, laissez-la tiedir et goutez-la froide avant de rectifier : crue, une farce de terrine trompe systematiquement le palais sur le sel et le poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Tassez un tiers de la farce au fond d''un moule a terrine d''environ 1,2 litre en chassant chaque poche d''air du poing, rangez dessus la moitie des lanieres de poulet bien a plat et tete-beche, couvrez d''un deuxieme tiers de farce, puis du reste des lanieres, et finissez par la farce restante. Disposez les lanieres perpendiculairement a la longueur du moule : c''est ainsi que la tranche montrera des etages nets plutot que des accidents. Lissez la surface en la bombant legerement, puis fermez avec le couvercle ou une double feuille d''aluminium bien serree.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Posez la terrine dans un plat creux, versez de l''eau bouillante jusqu''a mi-hauteur du moule et enfournez a 150 degres pendant deux heures ; le coeur doit atteindre 72 degres au thermometre a sonde, la terrine doit nager dans un jus clair et non rose.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Sortez le moule du bain-marie, decouvrez-le, posez une planchette a sa taille lestee d''environ 500 g et laissez refroidir ainsi a temperature ambiante, puis reservez la terrine pressee 24 a 48 heures au refrigerateur avant de tailler la premiere tranche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-058-D1', 'recipe_family', 'Terrine de campagne au poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-058-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-058-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-058-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('acbb9ac7c88c73879c77eea1de81cd4e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["porc gras","volaille saisie","poivre noir","eau-de-vie"],"aroma_families":["herbacé","alliacé","boisé"],"target_textures":["farce grossière","lanières de volaille fermes","tranche en étages"],"signature_ingredients":["Échine de porc crue","Poitrine de porc crue","Cognac"],"identity_guardrails":["Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.","Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.","Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identité de charcuterie de garde.","Les lanières de poulet se rangent en étages et doivent se voir à la coupe : hachées avec le reste, elles ne feraient qu''appauvrir la farce en gras sans rien apporter à la tranche."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Terrine de campagne aux poivrons et aux olives', 'terrine de campagne aux poivrons et aux olives', 'France', 'France',
     'meal', 'charcuterie', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Terrine de campagne aux poivrons et aux olives', 'Terrine de porc haché avec poivrons rôtis et olives en garniture intercalée', ds.id, 'SRC-058-D2',
    'Myko', 'editorial', 8, 55, 150, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e91cc669d7280510185581c5ae5f2482',
    '{"sweet":1,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['porc gras','poivron confit','olive noire','poivre noir']::text[],
    ARRAY['herbacé','alliacé','végétal grillé']::text[], ARRAY['farce grossière','lanières de poivron fondantes','tranche piquée de morceaux']::text[],
    ARRAY['Échine de porc crue','Poitrine de porc crue','Cognac']::text[], ARRAY['Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.','Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.','Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identité de charcuterie de garde.','Poivron et olives s''ajoutent en fin de mélange et restent en morceaux visibles : broyés avec la farce, ils la colorent et la détrempent sans rien donner à la coupe.']::text[],
    ARRAY['marinade','hachage','bain-marie','pressage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Repos obligatoire de 24 a 48 heures entre 0 et 4 degres avant la premiere tranche. Entiere et couverte de sa graisse figee, la terrine se garde 8 a 10 jours au refrigerateur ; une fois entamee, filmez la coupe au contact et consommez sous 4 jours. La congelation est possible en portions filmees jusqu''a 2 mois, mais elle detend la farce et rend la tranche plus friable a la decongelation, qui doit se faire une nuit au refrigerateur.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-058'), '{"variant_label":"Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.","rationale":"Le poivron confit et les olives entrent en morceaux dans une farce déjà liée : la tranche se pique de rouge et de noir, et le gras du porc trouve enfin en face de lui une douceur acidulée et un salé fruité qui l''allègent en bouche. Le prix est une terrine plus humide et plus fragile — le poivron rend de l''eau même longuement égoutté, et chaque morceau est une amorce de rupture de plus dans une tranche qui doit déjà se tenir seule. Le sel demande aussi d''être revu à la baisse, les olives en apportant une part que la macération ne prévoyait pas.","operations":[{"op":"add","form":"Poivron rouge frais","quantity":250,"unit":"g","role":"garniture","optional":false},{"op":"add","form":"Olive noire dénoyautée","quantity":80,"unit":"g","role":"garniture","optional":false}],"steps":[{"op":"insert","after":4,"instruction":"Passez les poivrons rouges au four a 200 degres une trentaine de minutes, jusqu''a ce que la peau cloque et noircisse par plaques, enfermez-les dix minutes dans un saladier couvert puis pelez-les et otez graines et cloisons. Taillez la chair en lanieres d''un centimetre et laissez-les s''egoutter a plat sur un papier absorbant : un poivron confit qui garde son jus le rendra dans la farce, et une farce mouillee ne se tranche pas. Detaillez les olives en deux ou en trois selon leur taille, sans jamais les hacher."},{"op":"replace","n":6,"instruction":"Incorporez le porc hache cru, les oeufs battus, la fondue d''aromates refroidie et le persil cisele, puis travaillez la farce a la main pendant deux a trois minutes, jusqu''a ce qu''elle devienne franchement collante et se decolle des parois en un seul bloc. Ajoutez seulement alors les lanieres de poivron et les olives, et melangez a la spatule en une dizaine de gestes larges : incorpores plus tot, ils seraient reduits en puree par le travail de la farce, or c''est leur integrite en morceaux qui fait tout l''interet de cette version."},{"op":"replace","n":7,"instruction":"Poelez une petite boulette de farce prelevee avec un morceau d''olive dedans, laissez-la tiedir et goutez-la froide avant de rectifier : crue, une farce de terrine trompe systematiquement le palais sur le sel et le poivre. Attendez-vous ici a ne rien ajouter, voire a regretter d''avoir sale a seize grammes — les olives apportent leur propre saumure et continueront de la diffuser pendant les deux heures de cuisson."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
