  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faites vos courses en poids d''achat, pas en poids net : demandez 250 g de poitrine de porc avec sa couenne, qui ne laissera qu''environ 200 g de chair une fois paree, 300 g d''echine a desosser pour 275 g de viande, et 400 g de porc deja hache. Une tete d''ail fournit les 15 g de gousses epluchees, une petite botte de persil les 18 g de feuilles, deux gros oeufs les 100 g hors coquille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Otez la couenne, les cartilages et les esquilles de la poitrine, desossez l''echine, puis taillez les deux viandes en cubes de deux centimetres sans retirer le gras : c''est lui qui donnera sa tenue et son moelleux a la tranche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Reunissez les cubes dans un grand saladier avec le cognac, le sel fin, le poivre noir moulu et le thym seche, melangez a pleines mains, couvrez et laissez macerer deux heures au refrigerateur pour que l''assaisonnement penetre le muscle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, epluchez l''oignon jaune et les echalotes, hachez-les finement et faites-les fondre a feu doux dans une poele a peine huilee, sans les colorer ; ajoutez l''ail ecrase a la toute fin, debarrassez et laissez refroidir completement avant tout contact avec la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passez les poivrons rouges au four a 200 degres une trentaine de minutes, jusqu''a ce que la peau cloque et noircisse par plaques, enfermez-les dix minutes dans un saladier couvert puis pelez-les et otez graines et cloisons. Taillez la chair en lanieres d''un centimetre et laissez-les s''egoutter a plat sur un papier absorbant : un poivron confit qui garde son jus le rendra dans la farce, et une farce mouillee ne se tranche pas. Detaillez les olives en deux ou en trois selon leur taille, sans jamais les hacher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Passez la viande maceree au hachoir muni de la grille de 8 mm, puis repassez seulement un gros tiers du hachis a la grille fine : ce tiers apportera le liant, le reste doit rester franchement grossier, c''est la signature d''une campagne face a une mousse de foie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporez le porc hache cru, les oeufs battus, la fondue d''aromates refroidie et le persil cisele, puis travaillez la farce a la main pendant deux a trois minutes, jusqu''a ce qu''elle devienne franchement collante et se decolle des parois en un seul bloc. Ajoutez seulement alors les lanieres de poivron et les olives, et melangez a la spatule en une dizaine de gestes larges : incorpores plus tot, ils seraient reduits en puree par le travail de la farce, or c''est leur integrite en morceaux qui fait tout l''interet de cette version.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Poelez une petite boulette de farce prelevee avec un morceau d''olive dedans, laissez-la tiedir et goutez-la froide avant de rectifier : crue, une farce de terrine trompe systematiquement le palais sur le sel et le poivre. Attendez-vous ici a ne rien ajouter, voire a regretter d''avoir sale a seize grammes — les olives apportent leur propre saumure et continueront de la diffuser pendant les deux heures de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Tassez la farce par couches dans un moule a terrine d''environ 1,2 litre en chassant chaque poche d''air du poing, lissez la surface en la bombant legerement, puis fermez avec le couvercle ou une double feuille d''aluminium bien serree.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Posez la terrine dans un plat creux, versez de l''eau bouillante jusqu''a mi-hauteur du moule et enfournez a 150 degres pendant deux heures ; le coeur doit atteindre 72 degres au thermometre a sonde, la terrine doit nager dans un jus clair et non rose.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Sortez le moule du bain-marie, decouvrez-le, posez une planchette a sa taille lestee d''environ 500 g et laissez refroidir ainsi a temperature ambiante, puis reservez la terrine pressee 24 a 48 heures au refrigerateur avant de tailler la premiere tranche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-058-D2', 'recipe_family', 'Terrine de campagne aux poivrons et aux olives',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-058-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-058-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-058-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e91cc669d7280510185581c5ae5f2482'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["porc gras","poivron confit","olive noire","poivre noir"],"aroma_families":["herbacé","alliacé","végétal grillé"],"target_textures":["farce grossière","lanières de poivron fondantes","tranche piquée de morceaux"],"signature_ingredients":["Échine de porc crue","Poitrine de porc crue","Cognac"],"identity_guardrails":["Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.","Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.","Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identité de charcuterie de garde.","Poivron et olives s''ajoutent en fin de mélange et restent en morceaux visibles : broyés avec la farce, ils la colorent et la détrempent sans rien donner à la coupe."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Terrine de campagne en bocaux', 'terrine de campagne en bocaux', 'France', 'France',
     'meal', 'charcuterie', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Terrine de campagne en bocaux', 'Terrine de campagne conditionnée en bocaux stérilisés pour une conservation longue durée', ds.id, 'SRC-058-D3',
    'Myko', 'editorial', 8, 40, 55, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '9ef271331b5ae990afadadd331ee420c',
    '{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['porc gras','poivre noir','ail','eau-de-vie']::text[],
    ARRAY['herbacé','alliacé','boisé']::text[], ARRAY['farce grossière','texture lâche qui se prend à la cuillère','surface colorée']::text[],
    ARRAY['Échine de porc crue','Poitrine de porc crue','Cognac']::text[], ARRAY['Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.','Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.','Le bocal remplace le moule et le pressage : la farce s''y tasse seule et se sert à la cuillère. Lui demander une tranche nette, c''est lui demander d''être une autre recette.','La cuisson en bocal n''est pas une stérilisation : le repos de 24 heures au froid et la chaîne du froid ensuite restent entiers.']::text[],
    ARRAY['marinade','hachage','bain-marie','pressage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Comptez 24 heures au réfrigérateur avant d''ouvrir le premier bocal, le temps que la farce se raffermisse et que l''assaisonnement s''égalise. Fermés et couverts de leur graisse figée, les bocaux se gardent 8 à 10 jours entre 0 et 4 degrés : quarante-cinq minutes de bain-marie cuisent la farce à cœur mais ne stérilisent rien, et aucune règle de froid ne saute. Un bocal entamé se consomme sous 4 jours, sa surface lissée et remise au contact de sa graisse. La congélation est possible par bocal jusqu''à 2 mois, mais elle détend une farce déjà plus friable que celle d''une terrine pressée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-058'), '{"variant_label":"Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.","rationale":"La cuisson en bocaux change l''échelle et donc les temps : quarante-cinq minutes à 200 degrés au lieu de deux heures à 150, parce qu''un petit volume monte en température beaucoup plus vite. La terrine y gagne un portionnement immédiat et des contenants qu''on entame un à un, elle y perd la tranche — sans pressage, la farce reste lâche et friable, elle se prend à la cuillère plutôt qu''au couteau. La coloration finale à découvert remplace la croûte que donnait le grand moule, mais elle ne concerne que la surface : le reste n''a jamais vu la chaleur sèche.","operations":[],"steps":[{"op":"replace","n":8,"instruction":"Repartissez la farce dans quatre a six bocaux a joint d''environ 350 ml, ebouillantes et parfaitement secs, en tassant chaque couche a la cuillere pour chasser l''air. Arretez-vous a deux bons centimetres du bord : la farce gonfle a la chaleur et un bocal trop plein deborde dans le bain-marie. Essuyez soigneusement le col avant de poser le couvercle sans le verrouiller."},{"op":"replace","n":9,"instruction":"Rangez les bocaux dans un plat creux assez haut, versez de l''eau bouillante jusqu''aux deux tiers de leur hauteur et enfournez a 200 degres pendant quarante-cinq minutes. Le volume est petit et la chaleur bien plus vive qu''au moule a terrine : quarante-cinq minutes suffisent la ou une grande terrine en demande deux. Verifiez au thermometre a sonde que le coeur d''un bocal atteint bien 72 degres avant d''aller plus loin."},{"op":"replace","n":10,"instruction":"Otez les couvercles et laissez les bocaux dix minutes de plus a decouvert, le temps que la surface prenne couleur, puis sortez-les du bain-marie. Aucun pressage ici : la farce refroidit dans son bocal et s''y tasse d''elle-meme, ce qui donne une charcuterie plus tendre et plus friable qu''une tranche lestee. Verrouillez les couvercles a chaud, laissez refroidir a temperature ambiante puis comptez 24 heures au refrigerateur avant d''ouvrir le premier bocal."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
