    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-058-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('21a61b746733612bad15c9a7f7315f83'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["porc gras","miel et épices douces","poivre noir","eau-de-vie"],"aroma_families":["herbacé","alliacé","épicée douce"],"target_textures":["farce grossière mais resserrée","tranche compacte","fondant gras"],"signature_ingredients":["Échine de porc crue","Poitrine de porc crue","Cognac"],"identity_guardrails":["Sans la part de gras apportée par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.","Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du côté du pâté de foie.","Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identité de charcuterie de garde.","Le pain d''épices reste une trace : soixante grammes pour près d''un kilo de viande arrondissent le poivre, le double sucrerait la terrine et la ferait basculer du côté d''un pâté de fête."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
