  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1a1c87ec18b07b9d46a700385b06620d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["amande torréfiée","citron","beurre fondu"],"aroma_families":["fruit à coque torréfié","agrume","lacté"],"target_textures":["chair floconneuse","amandes sèches et cassantes","surface farinée dorée"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["Les amandes sont grillées à sec et semées au dernier moment : versées dans la sauce, elles s''imbibent en quelques secondes et le croquant sec que vise cette version disparaît.","Le beurre reste la matière grasse de la sauce, même réduit à dix grammes : sans lui le jus de citron ne se lie pas et le plat n''est plus qu''un poisson fariné arrosé d''acide.","La truite est farinée puis saisie à la poêle, peau comprise ; pochée, fumée ou gratinée, elle sort de l''identité du plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
