  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les écailler, de les vider et d''ôter l''arête centrale. Une fois la tête et les nageoires retirées, il reste environ 520 g de chair, ce qui correspond à la quantité utile de la recette. Rincer à l''eau froide et sécher soigneusement avec du papier absorbant : une chair humide ne dore pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les deux faces des poissons, puis les passer dans la farine T55 étalée sur une assiette. Tapoter franchement pour ne garder qu''un voile : le surplus brûlerait dans la poêle et masquerait le goût de l''amande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire chauffer l''huile d''olive avec le tiers du beurre dans une grande poêle sur feu moyen-vif. Déposer les truites côté peau et les laisser prendre couleur environ cinq minutes sans y toucher, puis les retourner deux à trois minutes côté chair. La chair doit se détacher en lamelles opaques sous la pointe d''un couteau. Les laisser dans la poêle cette fois : c''est là qu''elles vont être flambées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Tiédir le cognac quelques secondes dans une petite casserole — un alcool froid ne s''enflamme pas —, couper la hotte, le verser sur les truites et l''enflammer aussitôt en tenant le manche à bout de bras et le visage écarté. Laisser la flamme s''éteindre d''elle-même, une demi-minute environ : elle brûle l''alcool et ne laisse que le parfum de fût accroché à la peau dorée. Réserver ensuite les poissons au chaud sur le plat de service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ne pas essuyer la poêle cette fois : le fond porte le cognac réduit avec les sucs, et c''est lui qui fera la sauce. Y faire fondre le reste du beurre sur feu doux et verser les amandes effilées. Remuer sans arrêt trois à quatre minutes jusqu''au blond noisette, en surveillant de près — le sucre laissé par l''alcool les colore plus vite que dans un beurre propre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer la poêle du feu, verser le jus de citron sur les amandes et faire tourner la poêle pour lier le beurre, les sucs et l''acidité en une sauce ambrée. En napper aussitôt les truites et servir sans attendre, tant que les amandes croquent encore.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-060-D2', 'recipe_family', 'Truite flambée au cognac et aux amandes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-060-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-060-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c22b41fc2465bd303d54221868514f10'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["beurre noisette","amande grillée","eau-de-vie boisée"],"aroma_families":["lacté","fruit à coque torréfié","spiritueux vieilli"],"target_textures":["chair floconneuse","amandes croquantes","sauce ambrée aux sucs"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["L''alcool s''enflamme tiède et brûle jusqu''à extinction naturelle : étouffé trop tôt, il laisse dans la sauce une amertume d''alcool cru que rien ne rattrape ensuite.","La poêle ne s''essuie pas après le flambage : les sucs au cognac sont la sauce, les retirer ramène le plat à sa version d''origine sans rien lui avoir apporté.","L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Truite au four à la crème d''amandes', 'truite au four a la creme d amandes', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Truite au four à la crème d''amandes', 'Truite cuite au four sous une couche de crème fraîche et amandes effilées', ds.id, 'SRC-060-D3',
    'Myko', 'editorial', 4, 20, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ae3506f48fca6bc7ed8282be5cc18078',
    '{"sweet":1,"salty":2,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['crème cuite','amande fraîche','citron']::text[],
    ARRAY['lacté','fruit à coque','agrume']::text[], ARRAY['chair nacrée et moelleuse','amandes gonflées dans la crème','sauce courte liée au jus de cuisson']::text[],
    ARRAY['Truite crue','Amande effilée','Beurre doux']::text[], ARRAY['La cuisson se fait à couvert et sans coloration : découvrir le plat pour faire dorer la surface donne un gratin, c''est-à-dire autre chose que ce que cette version annonce.','Les amandes restent effilées et pour partie noyées dans la crème : réduites en poudre elles épaississent la sauce en frangipane salée, et il ne reste plus rien à croquer.','La truite est levée en filets et cuite nue, sans enrobage : un poisson enrobé délaverait son voile dans la crème et la troublerait.']::text[],
    ARRAY['cuisson au four','cuisson à couvert','liaison à la crème']::text[], ARRAY[]::text[], ARRAY['poisson','fruits à coque','lait']::text[],
    'Se garde 48 h au réfrigérateur à 4 °C dans le plat filmé, la crème protégeant la chair du dessèchement bien mieux que ne le faisait la sauce au beurre. Réchauffer à couvert une dizaine de minutes à 150 °C, jamais à la poêle où la crème tranche. Ne pas congeler : la crème se sépare au dégel et la truite rend son eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-060'), '{"variant_label":"Version au four : filets couverts d''une crème aux amandes effilées et enfournés à couvert une vingtaine de minutes, plus moelleuse mais sans croûte dorée.","rationale":"Le plat quitte la poêle pour le four et change de nature : filets nus, sans enrobage ni huile, couverts d''une crème aux amandes et cuits vingt minutes à couvert. La chair reste nacrée et ne peut plus se dessécher, la sauce se lie d''elle-même au jus rendu, et le service se fait à la cuillère plutôt qu''à la spatule. Le coût est double : ni croûte dorée ni beurre noisette, et deux cents millilitres de crème entière qui alourdissent nettement la part. Les amandes noyées gonflent au lieu de croquer, seul le tiers semé en surface garde un peu de mordant.","operations":[{"op":"remove","form":"Farine de blé T55"},{"op":"remove","form":"Huile d''olive vierge extra"},{"op":"set","form":"Beurre doux","quantity":20},{"op":"add","form":"Crème fraîche liquide entière","quantity":200,"unit":"ml","role":"sauce","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les écailler, de les vider et de lever les huit filets en ôtant la peau. Il reste environ 520 g de chair nue, ce qui correspond à la quantité utile de la recette. Passer le doigt à plat sur chaque filet pour repérer les arêtes oubliées et les tirer à la pince, puis éponger au papier absorbant."},{"op":"replace","n":2,"instruction":"Chauffer le four à 180 °C. Beurrer largement le fond d''un plat à four avec la moitié du beurre, saler et poivrer les filets sur les deux faces, puis les coucher côte à côte sans jamais les superposer : empilés, ils cuiraient à des vitesses différentes et ceux du dessous rendraient toute leur eau dans le plat."},{"op":"replace","n":3,"instruction":"Faire fondre le reste du beurre dans une petite casserole, retirer du feu et y verser la crème avec le jus de citron. Saler légèrement, mêler à la fourchette, puis ajouter les deux tiers des amandes effilées : elles vont gonfler pendant la cuisson et donner à la sauce un goût d''amande fraîche, laiteux, très loin du fruit grillé de la version à la poêle."},{"op":"replace","n":4,"instruction":"Napper les filets de cette crème aux amandes en la faisant couler jusqu''entre les pièces, semer le reste des amandes en surface, couvrir le plat d''une feuille d''aluminium bien pincée sur les bords et enfourner vingt minutes. La vapeur retenue sous la feuille cuit la truite sans jamais la saisir : elle reste nacrée et souple, mais aucune croûte ne se formera, et découvrir le plat pour la chercher ferait un tout autre plat."},{"op":"replace","n":5,"instruction":"Sortir le plat, ôter l''aluminium et laisser reposer trois minutes avant de servir à la cuillère, en récupérant la sauce liée au fond. Elle a bu le jus des filets et c''est ce qui fait l''intérêt de la version au four : présentée à part, elle n''aurait plus que le goût de la crème."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
