    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 200, 'ml', 'required',
     'sauce', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les écailler, de les vider et de lever les huit filets en ôtant la peau. Il reste environ 520 g de chair nue, ce qui correspond à la quantité utile de la recette. Passer le doigt à plat sur chaque filet pour repérer les arêtes oubliées et les tirer à la pince, puis éponger au papier absorbant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer le four à 180 °C. Beurrer largement le fond d''un plat à four avec la moitié du beurre, saler et poivrer les filets sur les deux faces, puis les coucher côte à côte sans jamais les superposer : empilés, ils cuiraient à des vitesses différentes et ceux du dessous rendraient toute leur eau dans le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire fondre le reste du beurre dans une petite casserole, retirer du feu et y verser la crème avec le jus de citron. Saler légèrement, mêler à la fourchette, puis ajouter les deux tiers des amandes effilées : elles vont gonfler pendant la cuisson et donner à la sauce un goût d''amande fraîche, laiteux, très loin du fruit grillé de la version à la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Napper les filets de cette crème aux amandes en la faisant couler jusqu''entre les pièces, semer le reste des amandes en surface, couvrir le plat d''une feuille d''aluminium bien pincée sur les bords et enfourner vingt minutes. La vapeur retenue sous la feuille cuit la truite sans jamais la saisir : elle reste nacrée et souple, mais aucune croûte ne se formera, et découvrir le plat pour la chercher ferait un tout autre plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir le plat, ôter l''aluminium et laisser reposer trois minutes avant de servir à la cuillère, en récupérant la sauce liée au fond. Elle a bu le jus des filets et c''est ce qui fait l''intérêt de la version au four : présentée à part, elle n''aurait plus que le goût de la crème.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-060-D3', 'recipe_family', 'Truite au four à la crème d''amandes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-060-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-060-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ae3506f48fca6bc7ed8282be5cc18078'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["crème cuite","amande fraîche","citron"],"aroma_families":["lacté","fruit à coque","agrume"],"target_textures":["chair nacrée et moelleuse","amandes gonflées dans la crème","sauce courte liée au jus de cuisson"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["La cuisson se fait à couvert et sans coloration : découvrir le plat pour faire dorer la surface donne un gratin, c''est-à-dire autre chose que ce que cette version annonce.","Les amandes restent effilées et pour partie noyées dans la crème : réduites en poudre elles épaississent la sauce en frangipane salée, et il ne reste plus rien à croquer.","La truite est levée en filets et cuite nue, sans enrobage : un poisson enrobé délaverait son voile dans la crème et la troublerait."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Filets de truite meunière aux amandes', 'filets de truite meuniere aux amandes', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Filets de truite meunière aux amandes', 'Filets de truite enrobés de farine, saisis au beurre et garnis d''amandes effilées', ds.id, 'SRC-060-D4',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '61954bcb64cfe1f3d84f1a24cdabd87a',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['beurre noisette','amande grillée','citron']::text[],
    ARRAY['lacté','fruit à coque torréfié','agrume']::text[], ARRAY['chair floconneuse','amandes croquantes','surface farinée dorée']::text[],
    ARRAY['Truite crue','Amande effilée','Beurre doux']::text[], ARRAY['L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme.','Le beurre est la matière grasse de la sauce ; remplacé par une crème ou une sauce montée à l''huile seule, ce n''est plus une truite aux amandes.','Le filet reste fariné et saisi à la poêle : c''est ce que la découpe ne change pas, et sans cet enrobage doré il ne reste qu''un poisson poêlé nappé de beurre.']::text[],
    ARRAY['saisie','cuisson courte','déglaçage','torréfaction']::text[], ARRAY[]::text[], ARRAY['poisson','fruits à coque','lait','gluten']::text[],
    'Se mange immédiatement, la sauce et les amandes perdant leur croquant en quelques minutes. Les restes se gardent 24 h à 4 °C dans une boîte hermétique, amandes séparées du poisson si possible, et se réchauffent doucement à la poêle ou se mangent froids. La truite cuite supporte mal la congélation (chair qui rend son eau) et les amandes blondies ramollissent au dégel : ne pas congeler le plat monté.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-060'), '{"variant_label":"Filets levés et dépouillés plutôt que poissons entiers : cuisson ramenée à deux minutes par face, service plus facile à table.","rationale":"Les truites sont levées en filets et dépouillées : la cuisson du poisson tombe de huit à quatre minutes, et personne ne trie d''arêtes dans son assiette. La chair nue prend la farine bien plus vite qu''une peau, il faut donc tapoter deux fois plus sous peine d''un enrobage épais qui roussit avant que le poisson soit chaud. On perd la peau croustillante, qui faisait la moitié du plaisir de la version entière, et toute marge d''erreur : deux minutes de trop et un filet mince est sec sans retour.","operations":[],"steps":[{"op":"replace","n":1,"instruction":"Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les vider, de lever les huit filets et d''en retirer la peau. Il reste environ 520 g de chair nue, ce qui correspond à la quantité utile de la recette. Passer le doigt à plat le long de chaque filet pour repérer les arêtes oubliées et les tirer à la pince, puis sécher soigneusement au papier absorbant : une chair humide ne dore pas."},{"op":"replace","n":2,"instruction":"Saler et poivrer les filets sur les deux faces, puis les passer dans la farine T55 étalée sur une assiette. Tapoter deux fois plus franchement que sur un poisson entier : sans peau pour la retenir, la chair nue en prend beaucoup, et l''excédent roussirait dans la poêle avant même que le filet soit cuit."},{"op":"replace","n":3,"instruction":"Faire chauffer l''huile d''olive avec le tiers du beurre dans une grande poêle sur feu moyen-vif. Coucher les filets côté peau, celui qui vient d''être dépouillé, et les laisser deux minutes sans y toucher, puis les retourner deux minutes de l''autre côté. Ils sont minces et cuisent presque instantanément : une minute de trop et la chair se casse en la soulevant. Réserver au chaud sur le plat de service."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
