       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-060-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-060-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('61954bcb64cfe1f3d84f1a24cdabd87a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["beurre noisette","amande grillée","citron"],"aroma_families":["lacté","fruit à coque torréfié","agrume"],"target_textures":["chair floconneuse","amandes croquantes","surface farinée dorée"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme.","Le beurre est la matière grasse de la sauce ; remplacé par une crème ou une sauce montée à l''huile seule, ce n''est plus une truite aux amandes.","Le filet reste fariné et saisi à la poêle : c''est ce que la découpe ne change pas, et sans cet enrobage doré il ne reste qu''un poisson poêlé nappé de beurre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gigot d''agneau aux flageolets en conserve', 'gigot d agneau aux flageolets en conserve', 'France', 'France',
     'meal', 'plat complet rôti', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gigot d''agneau aux flageolets en conserve', 'Gigot d''agneau rôti avec haricots flageolets en conserve cuits au beurre avec thym et laurier', ds.id, 'SRC-003-D2',
    'Myko', 'editorial', 6, 25, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6201111c9f4e673bfa959dc2efa470a1',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":3,"freshness":4,"intensity":1}'::jsonb, ARRAY['agneau_rôti','ail_confit','haricot_fondant']::text[],
    ARRAY['viande_rôtie','ail','thym']::text[], ARRAY['croûte_dorée','chair_rosée','haricot_fondant']::text[],
    ARRAY['Gigot d''agneau cru','Haricot flageolet appertisé, égoutté','Ail cru']::text[], ARRAY['Le gigot repose avant d''être tranché, sinon le jus part sur la planche.','Les flageolets ne sont pas un accompagnement rapporté : ils finissent dans le jus de rôtissage.','La conserve ne se recuit pas : dix minutes à couvert suffisent à la parfumer, au-delà la peau éclate et le lit tourne en purée.']::text[],
    ARRAY['rôtissage','repos de la viande','liaison au beurre']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'La viande tranchée se garde 2 jours au froid ; les flageolets 2 jours seulement, une conserve déjà réchauffée une fois supportant mal un second passage sur le feu. Les remettre alors à couvert sur feu très doux, sans remuer, le temps qu''ils soient chauds à cœur.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-003'), '{"variant_label":"Flageolets en conserve, égouttés et réchauffés","rationale":"La conserve supprime le trempage et l''heure de frémissement : le rôtissage devient la seule cuisson longue et le plat perd cinquante minutes de feu. Ce qu''il perd avec elles, c''est le bouillon de haricot, où l''oignon, le thym et le laurier avaient une heure pour se défaire — ils n''ont plus ici qu''un réchauffage de dix minutes à couvert, et le lit de flageolets est d''autant plus neutre. Le grain arrive déjà cuit et déjà salé : il ne supporte pas l''ébullition, qui le réduit en purée, et le sel de la recette descend de 14 à 11 g. Il faut 1050 g de conserve égouttée pour retrouver le volume que rendaient 500 g de sec — le volume seulement : le flageolet appertisé porte trois fois moins de protéines que le sec, et le lit en perd environ un tiers.","operations":[{"op":"substitute","form":"Haricot flageolet sec","with":"Haricot flageolet appertisé, égoutté","quantity":1050,"unit":"g","role":"féculent"},{"op":"set","form":"Sel fin","quantity":11}],"steps":[{"op":"remove","n":1},{"op":"replace","n":2,"instruction":"Verser les haricots flageolets appertisés dans une passoire et les rincer à l''eau froide pour ôter le jus de conserve, qui est salé et un peu farineux, puis les laisser s''égoutter le temps du rôtissage. Peler l''oignon et le garder entier ; réserver à côté de lui le laurier et la petite part de thym destinée aux haricots, le reste du thym partant sur le gigot. La conserve étant déjà cuite, ces aromates n''auront que le réchauffage final pour se faire entendre, et il ne sert à rien de les mettre à l''eau maintenant."},{"op":"replace","n":3,"instruction":"Peler l''ail et le tailler en éclats. Inciser le gigot à intervalles réguliers et glisser un éclat dans chaque fente."},{"op":"replace","n":7,"instruction":"Pendant que le gigot repose, réchauffer les flageolets égouttés dix minutes à couvert et à feu doux avec l''oignon entier, le thym et le laurier, sans ajouter d''eau et sans remuer plus que nécessaire : le grain est déjà cuit, une ébullition le réduirait en purée. Les deux dix minutes se recouvrent exactement, et c''est voulu : un gigot qui attendrait en plus le réchauffage du lit se trancherait froid. Retirer les aromates, goûter avant de saler — la conserve en apporte déjà —, puis lier au beurre et au jus de rôtissage dégraissé et servir le gigot tranché sur ce lit."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

