    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Lentilles tièdes au jambonneau effiloché', 'Lentilles corail tièdes avec œuf poché et effilochée de jambonneau', ds.id, 'SRC-014-D5',
    'Myko', 'editorial', 4, 30, 65, 'facile',
    NULL, NULL,
    'B', 'candidate', '17cf83057ce50015903a38e197b78834',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['terreux','porc cuit','acidulé','herbacé','alliacé']::text[],
    ARRAY['herbacé','aromates séchés','alliacé','viande pochée']::text[], ARRAY['lentilles fondantes mais entières','viande effilochée fondante','jaune d''œuf coulant','éclats de noix croquants','oignon cru croquant']::text[],
    ARRAY['Lentille corail sèche, crue','Jambonneau cuit','Huile d''olive vierge extra','Vinaigre de vin rouge','Persil frais']::text[], ARRAY['Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.','L''eau de cuisson des lentilles reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.','La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.','La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît.','Le jambonneau entre effiloché et tiède, avant la vinaigrette : posé froid par-dessus au dernier moment, il ne boit rien et redevient une tranche de charcuterie à côté d''une salade.']::text[],
    ARRAY['mijotage','pochage','émulsion']::text[], ARRAY[]::text[], ARRAY['œuf','fruits à coque','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, vinaigrette déjà incorporée — la viande effilochée ramène la salade de trois jours à deux. Sortir 30 minutes avant le service ou réchauffer 1 minute à la poêle à feu doux pour retrouver la tiédeur. Les œufs mollets ne se conservent pas plus de 24 h et se posent au dernier moment. Congélation à proscrire : la lentille corail se délite en purée à la décongélation et les herbes fraîches noircissent.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-014'), '{"variant_label":"Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.","rationale":"Le jambonneau fait basculer la salade tiède en plat unique : 400 g de viande effilochée pour quatre parts s''ajoutent aux lentilles et à l''œuf, sans que rien ne soit retiré — 400 g de chair, ce qui veut dire une pièce d''environ 700 g avec son os, sa couenne et son gras. Il coûte une heure de pochage qui doit commencer avant tout le reste, plus 80 g de carotte et 80 g d''oignon pour son bouillon — les tronçons de carotte sont récupérés et rejoignent la salade, l''oignon a donné ce qu''il avait et reste au bouillon. La viande s''incorpore tiède, avant la vinaigrette comme la phrase le demande : c''est elle et le grain qui doivent boire l''assaisonnement ensemble, sinon le jus reste en fond de saladier. Le plat devient nettement plus salé et se garde deux jours au lieu de trois.","operations":[{"op":"add","form":"Jambonneau cuit","quantity":400,"unit":"g","role":"protéine","optional":false},{"op":"set","form":"Carotte crue","quantity":200},{"op":"set","form":"Oignon jaune cru","quantity":180}],"steps":[{"op":"replace","n":1,"instruction":"Mettre le jambonneau à cuire avant tout le reste : en prendre un d''environ 700 g avec son os, c''est ce qu''il faut pour rendre les 400 g de chair annoncés. Le poser dans une cocotte, le couvrir largement d''eau froide, y jeter 80 g de carotte pelée en gros tronçons et 80 g d''oignon en quartiers, porter au frémissement et laisser cuire une heure à couvert. Il en ressort moins salé et assez détendu pour s''effilocher à la fourchette. Pendant la première demi-heure, rincer les lentilles sous l''eau froide dans une passoire fine jusqu''à ce que l''eau ressorte claire. Peler le reste de la carotte et le tailler en rondelles de 3 mm, fendre le poireau et le débiter en fines demi-rondelles après l''avoir bien lavé. Peler le reste de l''oignon et le couper en deux : une moitié partira entière à la cuisson des lentilles, l''autre sera émincée crue au dernier moment. Ne mettre les lentilles sur le feu qu''une vingtaine de minutes avant la fin du pochage : le temps de monter en température et de cuire, elles seront tièdes à point quand la viande sortira. Lancées en même temps que le jambonneau, elles auraient quarante minutes à refroidir dans le saladier et ne boiraient plus rien."},{"op":"insert","after":5,"instruction":"Sortir le jambonneau de son bouillon, le laisser tiédir dix minutes puis l''effilocher à la fourchette en écartant l''os, la couenne et le gras ferme. Repêcher aussi les tronçons de carotte, qui ont pris le goût de la viande, et les couper en rondelles ; l''oignon du bouillon, lui, a donné ce qu''il avait et n''a plus rien à faire dans la salade. Verser viande et carotte sur les lentilles encore tièdes et mélanger tout de suite, avant d''assaisonner."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
