     'aromate', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Immerger les œufs dans une casserole d''eau frémissante et compter dix minutes à petits bouillons, puis les refroidir sous l''eau courante, les écaler et les couper en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir la tomate râpée dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser macérer un quart d''heure le temps que le jus se colore et se parfume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Profiter du quart d''heure de macération pour écosser les fèves : compter environ quatre cents grammes de gousses pour obtenir les cent vingt grammes de grains utiles. Goûter un grain cru — sur une févette de printemps, la fine robe qui l''enveloppe est encore tendre et se mange telle quelle ; si elle accroche déjà sous la dent, l''entamer de l''ongle au sommet du grain et la faire glisser, sans passer par l''eau bouillante qui cuirait ce qui doit rester cru. Émincer l''oignon nouveau en lamelles très fines, le vert de la tige compris, puis le laisser tremper cinq minutes à l''eau froide avant de l''égoutter et de l''éponger : ainsi rincé de son jus le plus agressif, il ne prendra pas le dessus pendant l''heure de repos.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fendre le pain de campagne en deux dans l''épaisseur et creuser légèrement la mie de la partie supérieure pour ménager de la place à la garniture et à l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Badigeonner les deux faces internes avec l''huile d''olive restante, puis les arroser du jus rendu par la tomate jusqu''à ce que la mie soit franchement humide sans être détrempée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la tomate râpée égouttée sur la base, répartir dessus les rondelles d''œuf dur, puis semer les fèves écossées et les lamelles d''oignon nouveau en les glissant entre les rondelles plutôt qu''en surface : posées sur le dessus, elles roulent hors du pain dès la première pression. Parsemer enfin d''olives noires dénoyautées et grossièrement concassées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier et laisser reposer trente à soixante minutes au frais avant de découper en quatre parts.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-017-D4', 'recipe_family', 'Pan bagnat niçois de printemps',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-017-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-017-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-017-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ea468577f8d4742ba62f5d65069bc17c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["tomate mûre","huile d''olive fruitée","olive noire","acidité vinaigrée"],"aroma_families":["fruité olive","végétal frais","acidulé vinaigré"],"target_textures":["mie imbibée et moelleuse","croûte souple","jaune d''œuf crémeux"],"signature_ingredients":["Pain de campagne","Huile d''olive vierge extra","Tomate râpée","Olive noire"],"identity_guardrails":["La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.","Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.","Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.","Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
