  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('501241298f9f7646d23383541d1f271e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["tomate","huile d''olive","poivron vert"],"aroma_families":["végétal","fruité"],"target_textures":["grains de riz détachés","dés de poivron croquants","enrobage huileux léger"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Riz cru","Huile d''olive vierge extra"],"identity_guardrails":["Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.","Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.","Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
