  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler l''épaule de porc en cubes réguliers d''environ quatre centimètres, assez gros pour rester moelleux après une cuisson longue. Peler et émincer finement l''oignon jaune, tailler la carotte en petits dés. Fendre le chou rouge en quartiers, retirer le trognon central qui ne s''attendrit jamais, puis émincer les feuilles en lanières de la largeur d''un doigt : taillées plus fin, elles se défont en marmelade au bout d''une heure de cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile d''olive dans une cocotte à fond épais, y faire suer l''oignon et la carotte à feu moyen une dizaine de minutes, jusqu''à ce qu''ils deviennent translucides et souples sans prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pousser la garniture sur les bords, monter le feu et déposer les cubes de porc à plat. Les laisser dorer sans les bouger, puis les retourner face par face jusqu''à ce qu''ils soient colorés partout.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les lardons fumés et les laisser fondre deux à trois minutes en remuant, le temps qu''ils libèrent leur gras et parfument l''ensemble de la cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Jeter le chou rouge émincé dans la cocotte et le retourner deux minutes dans le gras rendu par les lardons, le temps qu''il commence à s''affaisser et qu''il prenne le goût du fond. Verser l''eau et gratter aussitôt à la cuillère en bois pour décoller les sucs caramélisés : le mouillement est ici plus court d''un tiers, parce que quatre cents grammes de chou lâchent bien plus que cela pendant la cuisson et qu''un jus trop abondant ne se rattrape pas. Ne pas en retirer davantage pour autant : il faut de quoi déglacer et de quoi couvrir le fond le temps que le chou s''affaisse et prenne le relais. Poivrer, porter à petits bouillons puis couvrir et baisser au minimum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser mijoter environ une heure à frémissement à peine perceptible, en remuant de loin en loin pour faire descendre dans le jus le chou resté en surface. Il perd les deux tiers de son volume et lâche son pigment, qui teinte la sauce et jusqu''aux cubes de porc. Piquer la viande : elle doit céder sans résistance sous la pointe du couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporer les pruneaux dénoyautés et poursuivre vingt minutes à couvert, juste assez pour qu''ils gonflent et parfument le jus sans se défaire en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère ; le chou ayant rendu davantage d''eau que les cent dix millilitres retirés au mouillement, prolonger de quelques minutes à feu plus vif si le jus reste fluide. Mélanger avec précaution et rectifier le poivre avant de servir. La couleur, à ce stade, a viré : faute d''acidité pour fixer son pigment, le chou longuement cuit abandonne le pourpre du cru pour un violet sombre qui tire sur le brun, et la sauce le suit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
