DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calamars à l''armoricaine au whisky', 'calamars a l armoricaine au whisky', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Calamars à l''armoricaine au whisky', 'Calamars flambés au whisky, mijotés dans une sauce tomate au vin blanc', ds.id, 'SRC-034-D2',
    'Myko', 'editorial', 4, 25, 55, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '966e77a064d622678d115d1c3c4e15a7',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate concentrée','iodé','whisky flambé','vin blanc']::text[],
    ARRAY['marin','céréalier fumé','vineux','alliacé']::text[], ARRAY['anneaux tendres sous la dent','sauce nappante','oignons fondus']::text[],
    ARRAY['Calamar cru nettoyé','Whisky','Concentré de tomate','Vin blanc sec']::text[], ARRAY['Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.','C''est le flambage qui est constitutif de l''armoricaine, pas l''eau-de-vie employée : l''alcool doit brûler dans la cocotte, versé cru il ne laisserait que son alcool.','La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.','Le whisky se choisit non tourbé : la fumée de tourbe recouvre l''iode du mollusque et donne à la sauce un goût médicinal que rien ne rattrape.']::text[],
    ARRAY['saisie','flambage','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['mollusques','sulfites','lait']::text[],
    'Se garde deux à trois jours au réfrigérateur à 4 °C dans un contenant hermétique, et gagne même à être préparé la veille. Réchauffer à feu très doux, sans ébullition, sous peine de raidir les calamars. La congélation est possible un mois mais dégrade nettement la texture du mollusque : mieux vaut congeler la sauce seule et cuire les calamars au moment.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-034'), '{"variant_label":"Remplacer le Cognac par un whisky, variante explicitement proposée par une source, pour une note plus fumée que fruitée.","rationale":"Le whisky prend la place du Cognac à volume égal : le flambage reste le même geste, mais le fond de sauce perd les notes de fruit confit de l''eau-de-vie de vin pour une amertume céréalière et fumée qui tient plus longtemps en bouche. Le coût est un risque de dosage plutôt qu''un coût calorique — les deux alcools pèsent presque le même poids d''éthanol, et l''apport par part ne bouge pas d''une dizaine de kilocalories. Ce qui change vraiment, c''est l''équilibre : un whisky tourbé recouvre l''iode du calamar et rend la sauce médicinale, si bien que la variante ne tient qu''avec un grain léger, non tourbé.","operations":[{"op":"substitute","form":"Cognac","with":"Whisky","quantity":32,"unit":"g","role":"alcool de flambage"}],"steps":[{"op":"replace","n":4,"instruction":"Remettre les calamars et leur jus dans la cocotte, monter le feu, verser le whisky et l''enflammer en écartant le visage et en éteignant la hotte. Attendre que la flamme retombe d''elle-même et la laisser aller jusqu''au bout : un alcool de grain brûle plus court qu''une eau-de-vie de vin et laisse au fond une amertume qu''il faut lui laisser perdre dans la flamme. Racler ensuite le fond à la cuillère en bois pour décoller ce qui a caramélisé."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

