  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 1,2 kg de calamars entiers chez le poissonnier pour obtenir les 800 g de chair nettoyée de la recette. Tirer la tête et les viscères hors du manteau, retirer la plume transparente, faire glisser la membrane violacée sous un filet d''eau froide, puis sectionner les tentacules juste au-dessus des yeux en éliminant le bec corné. Détailler les corps en anneaux d''environ un centimètre et demi et éponger le tout longuement dans un linge : une chair humide bout au lieu de dorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fumer l''huile d''olive dans une cocotte à fond épais et y jeter les anneaux et les tentacules en deux fournées, sans jamais tasser le fond. Laisser accrocher deux à trois minutes par fournée en remuant peu, le temps que les bords se marquent. Débarrasser au fur et à mesure dans une passoire posée sur un bol et conserver le jus qui s''y écoule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser sous la cocotte, y verser l''oignon jaune et l''échalote finement ciselés et les laisser suer une bonne huitaine de minutes en grattant les sucs, jusqu''à transparence et sans qu''ils blondissent. Ajouter l''ail haché seulement dans la dernière minute pour qu''il reste parfumé plutôt qu''amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre les calamars et leur jus dans la cocotte, monter le feu, verser le whisky et l''enflammer en écartant le visage et en éteignant la hotte. Attendre que la flamme retombe d''elle-même et la laisser aller jusqu''au bout : un alcool de grain brûle plus court qu''une eau-de-vie de vin et laisse au fond une amertume qu''il faut lui laisser perdre dans la flamme. Racler ensuite le fond à la cuillère en bois pour décoller ce qui a caramélisé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le concentré de tomate et le laisser pincer une à deux minutes contre le fond chaud : il fonce et perd son acidité crue. Incorporer alors la tomate râpée, mouiller avec le vin blanc sec, saler, poivrer et poudrer du piment de Cayenne. Le liquide doit affleurer les calamars sans les noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et maintenir un frémissement paresseux pendant trente-cinq minutes environ, en remuant deux ou trois fois. Les anneaux se raffermissent d''abord puis se détendent : goûter à partir de la trentième minute et prolonger si la chair résiste encore sous la dent. Retirer ensuite le couvercle et laisser réduire huit à dix minutes, jusqu''à ce que la sauce nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, lisser la sauce avec la crème fraîche liquide entière et parsemer du persil haché. Rectifier le sel, laisser reposer cinq minutes hors du feu pour que les parfums se rassemblent, puis servir brûlant avec un riz blanc long qui boira la sauce.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-034-D2', 'recipe_family', 'Calamars à l''armoricaine au whisky',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-034-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-034-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-034-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('966e77a064d622678d115d1c3c4e15a7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["tomate concentrée","iodé","whisky flambé","vin blanc"],"aroma_families":["marin","céréalier fumé","vineux","alliacé"],"target_textures":["anneaux tendres sous la dent","sauce nappante","oignons fondus"],"signature_ingredients":["Calamar cru nettoyé","Whisky","Concentré de tomate","Vin blanc sec"],"identity_guardrails":["Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.","C''est le flambage qui est constitutif de l''armoricaine, pas l''eau-de-vie employée : l''alcool doit brûler dans la cocotte, versé cru il ne laisserait que son alcool.","La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.","Le whisky se choisit non tourbé : la fumée de tourbe recouvre l''iode du mollusque et donne à la sauce un goût médicinal que rien ne rattrape."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calamars à la crème et au safran', 'calamars a la creme et au safran', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Calamars à la crème et au safran', 'Calamars flambés au cognac, mijotés dans un vin blanc lié à la crème fraîche au safran', ds.id, 'SRC-034-D3',
    'Myko', 'editorial', 4, 30, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '4e8f03c2fb7d3e1cace8ef55af6bc483',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['safran','iodé','crème','vin blanc']::text[],
    ARRAY['marin','safrané','lacté','vineux']::text[], ARRAY['anneaux fermes et juteux','sauce nappante','champignons colorés']::text[],
    ARRAY['Calamar cru nettoyé','Safran','Crème fraîche liquide entière','Vin blanc sec']::text[], ARRAY['Sans calamar, il n''y a plus de plat : c''est le mollusque qui porte l''identité, la crème et le safran ne font que l''habiller.','Le safran doit rester lisible sans dominer : les 0,2 g de la liste, soit la dose courante du commerce pour quatre, sont un plafond et non un point de départ — au-delà il vire au métallique et écrase l''iode.','La cuisson est courte ou elle est longue, jamais moyenne : douze minutes laissent l''anneau ferme, une heure le détend, la demi-heure le rend coriace.','Cette version abandonne la tomate et sort du registre de l''armoricaine : elle ne peut pas en revendiquer le nom, seulement la parenté.']::text[],
    ARRAY['saisie','flambage','déglaçage','cuisson courte','réduction']::text[], ARRAY[]::text[], ARRAY['mollusques','sulfites','lait']::text[],
    'Se garde 48 heures au réfrigérateur à 4 °C dans un contenant hermétique, mais ne gagne rien à attendre, contrairement à la version mijotée : la cuisson courte n''a pas détendu la chair et un jour de plus la raffermit. Réchauffer à feu très doux sans ébullition, la crème liée à froid tranchant dès le premier bouillon. Congélation déconseillée telle quelle — le safran s''affadit et la liaison rend son eau ; congeler à la rigueur les calamars et les champignons cuits sans crème, un mois, et lier au moment de servir.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-034'), '{"variant_label":"Version crème et safran de 750g.com : champignons de Paris avec les échalotes, cuisson courte, liaison à la crème et quelques pistils de safran à la place de la tomate.","rationale":"En perdant ses 510 g de base rouge, le plat perd aussi l''acidité et la mâche qui portaient la sauce : le safran devient l''axe du goût, la crème le liant, et les champignons rendent le volume végétal que la tomate occupait. La cocotte se vidant d''un tiers, le vin descend de 400 à 250 g — quatre cents grammes ne réduisent pas en douze minutes et laisseraient un bouillon acide. Le coût est double : la part passe d''une sauce maigre à une sauce montée à la crème, et la cuisson courte n''est tenable qu''à la minute près, le calamar étant tendre avant un quart d''heure et après une heure, coriace entre les deux. Le plat quitte le registre de l''armoricaine et ne peut plus en porter le nom.","operations":[{"op":"remove","form":"Concentré de tomate"},{"op":"remove","form":"Tomate râpée"},{"op":"add","form":"Champignon de Paris frais","quantity":250,"unit":"g","role":"légume","optional":false},{"op":"add","form":"Safran","quantity":0.2,"unit":"g","role":"épice","optional":false},{"op":"set","form":"Vin blanc sec","quantity":250},{"op":"set","form":"Crème fraîche liquide entière","quantity":200,"role":"liaison","optional":false},{"op":"set","form":"Échalote crue","quantity":40,"optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Baisser sous la cocotte, y verser l''oignon jaune et l''échalote finement ciselés et les laisser suer une bonne huitaine de minutes en grattant les sucs, jusqu''à transparence et sans qu''ils blondissent. Jeter alors les champignons de Paris émincés épais et remonter le feu : ils rendent d''abord toute leur eau, qu''il faut laisser s''évaporer sans couvrir, puis se colorent en cinq à six minutes — émincés trop fin ou étouffés sous un couvercle, ils se réduiraient à rien dans la sauce. Ajouter l''ail haché seulement dans la dernière minute pour qu''il reste parfumé plutôt qu''amer."},{"op":"replace","n":5,"instruction":"Mouiller avec le vin blanc sec, gratter le fond une dernière fois et laisser réduire de moitié à découvert : rien ne portera la sauce ici qu''elle-même, et c''est cette réduction seule qui lui donnera du corps. Écraser les pistils de safran entre les doigts, les jeter dans le liquide chaud et couper le feu deux minutes le temps qu''ils s''ouvrent — dans un liquide froid ils ne rendent rien, à gros bouillons ils rendent leur couleur sans leur parfum. Saler, poivrer, et ne poudrer le piment de Cayenne qu''à la pointe du couteau si l''on y tient : le safran s''efface derrière le piquant."},{"op":"replace","n":6,"instruction":"Couvrir et maintenir un frémissement paresseux douze minutes, pas davantage. Le calamar n''a que deux points de tendreté : avant un quart d''heure, quand il est encore ferme et juteux, et après une heure de mijotage, quand le collagène a cédé. Entre les deux il se raidit. Goûter donc à la dixième minute et trancher franchement : soit on sert tout de suite, soit on rallonge d''une heure — s''arrêter à la demi-heure donnerait la seule texture que personne ne cherche."},{"op":"replace","n":7,"instruction":"Couper le feu, verser la crème fraîche liquide entière en filet et la lier à la sauce safranée sans jamais la ramener à ébullition, sous peine de la voir se dissocier en grains autour des anneaux. Parsemer du persil haché, rectifier le sel, laisser reposer cinq minutes hors du feu pour que le safran finisse de se diffuser — c''est au repos qu''il prend sa couleur, pas à la cuisson — puis servir avec un riz blanc long, qui se teintera dans l''assiette."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

