  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 3 kg de coquilles entières pour quatre, soit une bonne douzaine de pièces lourdes et bien closes : une fois décoquillées et parées, elles rendent les 500 g de chair de la liste, le reste étant coquille, manteau et viscères. Les brosser sous un filet d''eau froide sans jamais les laisser tremper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Commencer par les morilles, qui demandent une demi-heure d''avance. Peser 20 g de morilles séchées — c''est le poids d''achat, elles reprendront huit à dix fois leur poids en eau et donneront les 180 g de la liste — les couvrir d''eau à peine frémissante et les laisser gonfler trente minutes. Les sortir à la main sans presser le bol, puis les rincer une par une sous un filet d''eau froide en écartant les alvéoles, où le sable se loge et ne part pas tout seul. Filtrer le jus de trempage au linge fin et le réserver : il porte tout ce que l''eau a pris au champignon, et le jeter serait perdre la moitié de l''intérêt du produit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Mettre de côté huit coquilles creuses, brossées puis passées à l''eau bouillante une minute, qui serviront de plats.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer une poêle jusqu''à ce qu''elle fume légèrement, y verser l''huile d''olive et saisir la chair bien sèche 45 secondes par face, en deux fois pour ne pas encombrer la poêle. Elle doit rester nacrée à cœur. La débarrasser aussitôt sur une assiette froide et garder le jus rendu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et le jus de trempage filtré, puis laisser réduire à feu moyen jusqu''à ce qu''il ne reste que deux ou trois cuillerées sirupeuses. Le trempage a doublé le volume à évaporer : compter cinq minutes de plus qu''à l''ordinaire et ne pas abréger, c''est cette réduction qui remplacera le liant de la version gratinée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Éponger les morilles dans un linge et les faire sauter à feu vif dans 25 g de beurre, cinq à six minutes, jusqu''à ce qu''elles cessent de rendre de l''eau et sentent la noisette. Ajouter l''ail haché fin pour la dernière minute seulement, saler d''une pincée et débarrasser hors du feu. Cette poêlée n''est pas facultative : la morille ne se mange ni crue ni juste tiédie, il lui faut une cuisson franche, et l''ail brûlé couvrirait le seul parfum du plat qui soit fragile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Casser les œufs entiers dans un saladier et les battre juste ce qu''il faut pour rompre les jaunes, sans les faire mousser. Verser la crème dessus en filet en fouettant, puis incorporer la réduction passée au tamis, tiède et surtout pas bouillante : versée brûlante elle prendrait les œufs en fils. L''appareil doit rester franchement liquide et ne nappe pas la cuillère — il n''y a rien ici pour l''épaissir sur le feu, c''est le four qui le fera prendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Poivrer l''appareil, y ciseler le persil, goûter et n''ajuster le sel qu''après : la réduction en apporte déjà beaucoup. Ne pas céder à la tentation de le chauffer pour l''épaissir — un mélange d''œufs entiers et de crème coagule vers 80 °C et grainerait dans la casserole avant même d''atteindre la coquille. On le monte froid, on l''enfourne aussitôt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Trancher les grosses pièces de chair en deux dans l''épaisseur et les répartir dans les coquilles creuses posées sur une plaque. Distribuer les morilles sautées par-dessus, puis verser l''appareil directement sur la chair, jusqu''aux deux tiers de la hauteur seulement : il gonfle un peu au four et déborderait d''une coquille remplie à ras. Saupoudrer de chapelure et parsemer des 5 g de beurre restants en tout petits éclats.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Enfourner à mi-hauteur d''un four préchauffé à 190 °C pour 14 à 16 minutes : l''appareil doit prendre comme un flan, à peine tremblant au centre, et la chapelure dorer sans plus. Plus chaud ou plus haut dans le four, il boursoufle puis retombe en rendant de l''eau autour de la chair, qui se rétracte du même coup. Servir sans attendre, les coquilles calées sur un lit de gros sel.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-039-D3', 'recipe_family', 'Coquilles Saint-Jacques aux morilles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-039-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-039-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-039-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3ab8adca170657513bfd6454823eee4e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["iodé","morille","crémeux beurré","ail"],"aroma_families":["marin","sous-bois","lacté","alliacé"],"target_textures":["chair nacrée et moelleuse","appareil pris comme un flan","croûte de chapelure croustillante"],"signature_ingredients":["Noix de Saint-Jacques crue","Morille crue","Crème fraîche liquide entière","Chapelure de blé"],"identity_guardrails":["Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.","Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.","La morille passe obligatoirement à la poêle avant le four : ni crue ni simplement réchauffée, elle reste indigeste.","L''appareil aux œufs entiers ne se cuit pas sur le feu, il prend au four : chauffé en casserole, il graine et la variante n''a plus de sauce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Coquilles Saint-Jacques scellées au four', 'coquilles saint jacques scellees au four', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Coquilles Saint-Jacques scellées au four', 'Noix de Saint-Jacques cuites dans leur coquille scellée au four dans une sauce crème', ds.id, 'SRC-039-D4',
    'Myko', 'editorial', 4, 35, 25, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'fbbae3c353d6e1cd097e4f0e93a9d1b9',
    '{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['iodé','crémeux beurré','vin blanc réduit','échalote fondue']::text[],
    ARRAY['marin','lacté','alliacé','vineux']::text[], ARRAY['chair nacrée et moelleuse','sauce nappante restée liquide','aucune croûte : tout est moelleux sous le couvercle']::text[],
    ARRAY['Noix de Saint-Jacques crue','Crème fraîche liquide entière','Vin blanc sec']::text[], ARRAY['Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.','Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.','Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes.','Dix minutes à 200 °C sont un plafond et non une durée à rallonger : la coquille scellée retient la chaleur, et la sauce liée aux jaunes graine dès qu''elle bout.']::text[],
    ARRAY['saisie','réduction','déglaçage','cuisson couverte']::text[], ARRAY[]::text[], ARRAY['mollusques','poisson','lait','œuf','gluten','sulfites']::text[],
    'Scellées mais non enfournées, les coquilles attendent 2 à 3 heures à 4 °C, pas davantage : le joint sèche, se fendille et ne tient plus la vapeur. Une fois ouvertes, elles se mangent tout de suite — il n''y a rien à réchauffer dans une coquille dont le sceau est rompu, et la sauce liée aux jaunes ne supporte pas un second passage au four. La chair crue parée ne dépasse pas 24 h posée sur un lit de glace. Congélation : acceptable pour la chair crue étalée à plat et bien épongée (2 mois), exclue pour le plat monté.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-039'), '{"variant_label":"Coquilles refermées et scellées d''un boudin de pâte à luter, cuites 10 minutes à 200 °C et ouvertes au couteau à table.","rationale":"La coquille refermée retient la vapeur au lieu de la laisser partir dans le four : la chair cuit dans son parfum, la sauce reste liquide et l''iode ne s''évapore pas, mais il n''y a plus de gratin, donc plus de chapelure ni de contraste croustillant. Ce que la variante achète, c''est le moment du service : le couvercle qui cède sous le couteau libère d''un coup une bouffée de vin et de mer que la version ouverte diffuse pendant la cuisson. Elle coûte cinq minutes de mise en place pour la pâte et le sertissage, et une vigilance nouvelle sur le four — sous une coquille close, une sauce liée aux jaunes monte vite en température et dix minutes sont un maximum, pas une indication.","operations":[{"op":"remove","form":"Chapelure de blé"}],"steps":[{"op":"replace","n":2,"instruction":"Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Garder ici les deux valves de huit coquilles, chaque plate appariée à la creuse dont elle vient, brossées puis passées à l''eau bouillante une minute. La plate servira de couvercle et doit retomber d''aplomb sur sa jumelle : deux valves dépareillées ne se rejoignent nulle part et le joint ne prendra pas."},{"op":"replace","n":7,"instruction":"Trancher les grosses pièces de chair en deux dans l''épaisseur, les répartir dans les coquilles creuses posées sur une plaque, napper de sauce sans remplir jusqu''au bord et parsemer des 5 g de beurre restants en tout petits éclats. Pétrir à part, dans un bol, deux grosses cuillerées de farine avec un filet d''eau froide, jusqu''à une pâte ferme et non collante. Prendre cette farine en plus des 25 g comptés pour le roux, qu''il ne faut pas entamer : la pâte à luter ne se mange pas, elle scelle, elle cuit et on la jette avec les valves — sacrifier le roux au joint laisserait une sauce sans liant. La rouler en boudins minces, en ceinturer le bord de chaque coquille creuse, poser le couvercle et pincer le joint tout autour du pouce et de l''index."},{"op":"replace","n":8,"instruction":"Enfourner à mi-hauteur d''un four préchauffé à 200 °C pour 10 minutes, montre en main. Sous la coquille close la chaleur ne s''échappe plus : la sauce ne doit pas y revenir à ébullition, sinon les jaunes qui la lient grainent sans retour, et la chair déjà saisie se rétracte. Le seul repère visible est le joint, qui durcit et brunit. Servir les coquilles brûlantes calées sur un lit de gros sel, avec la pointe d''un couteau pour rompre le sceau à table : c''est là que tout se joue, dans la bouffée d''iode et de vin qui sort quand le couvercle cède."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
