      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
