  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 3 kg de coquilles entières pour quatre, soit une bonne douzaine de pièces lourdes et bien closes : une fois décoquillées et parées, elles rendent les 500 g de chair de la liste, le reste étant coquille, manteau et viscères. Les brosser sous un filet d''eau froide sans jamais les laisser tremper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Garder ici les deux valves de huit coquilles, chaque plate appariée à la creuse dont elle vient, brossées puis passées à l''eau bouillante une minute. La plate servira de couvercle et doit retomber d''aplomb sur sa jumelle : deux valves dépareillées ne se rejoignent nulle part et le joint ne prendra pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer une poêle jusqu''à ce qu''elle fume légèrement, y verser l''huile d''olive et saisir la chair bien sèche 45 secondes par face, en deux fois pour ne pas encombrer la poêle. Elle doit rester nacrée à cœur. La débarrasser aussitôt sur une assiette froide et garder le jus rendu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et laisser réduire à feu moyen jusqu''à ce qu''il ne reste qu''un fond sirupeux, environ la moitié du volume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans une casserole à part, fondre 25 g de beurre, pluie de farine, remuer une minute à feu doux : le mélange doit mousser sans blondir. Verser la réduction passée au tamis puis la crème en trois fois, en fouettant. Laisser épaissir 5 minutes à petits bouillons jusqu''à ce que la sauce nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer du feu, attendre une minute, puis incorporer les jaunes d''œufs un par un au fouet — la sauce ne doit plus jamais bouillir, sous peine de grainer. Poivrer, ciseler le persil dedans, goûter et n''ajuster le sel qu''après : la réduction en apporte déjà beaucoup.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Trancher les grosses pièces de chair en deux dans l''épaisseur, les répartir dans les coquilles creuses posées sur une plaque, napper de sauce sans remplir jusqu''au bord et parsemer des 5 g de beurre restants en tout petits éclats. Pétrir à part, dans un bol, deux grosses cuillerées de farine avec un filet d''eau froide, jusqu''à une pâte ferme et non collante. Prendre cette farine en plus des 25 g comptés pour le roux, qu''il ne faut pas entamer : la pâte à luter ne se mange pas, elle scelle, elle cuit et on la jette avec les valves — sacrifier le roux au joint laisserait une sauce sans liant. La rouler en boudins minces, en ceinturer le bord de chaque coquille creuse, poser le couvercle et pincer le joint tout autour du pouce et de l''index.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Enfourner à mi-hauteur d''un four préchauffé à 200 °C pour 10 minutes, montre en main. Sous la coquille close la chaleur ne s''échappe plus : la sauce ne doit pas y revenir à ébullition, sinon les jaunes qui la lient grainent sans retour, et la chair déjà saisie se rétracte. Le seul repère visible est le joint, qui durcit et brunit. Servir les coquilles brûlantes calées sur un lit de gros sel, avec la pointe d''un couteau pour rompre le sceau à table : c''est là que tout se joue, dans la bouffée d''iode et de vin qui sort quand le couvercle cède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-039-D4', 'recipe_family', 'Coquilles Saint-Jacques scellées au four',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-039-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-039-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-039-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fbbae3c353d6e1cd097e4f0e93a9d1b9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["iodé","crémeux beurré","vin blanc réduit","échalote fondue"],"aroma_families":["marin","lacté","alliacé","vineux"],"target_textures":["chair nacrée et moelleuse","sauce nappante restée liquide","aucune croûte : tout est moelleux sous le couvercle"],"signature_ingredients":["Noix de Saint-Jacques crue","Crème fraîche liquide entière","Vin blanc sec"],"identity_guardrails":["Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.","Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.","Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes.","Dix minutes à 200 °C sont un plafond et non une durée à rallonger : la coquille scellée retient la chaleur, et la sauce liée aux jaunes graine dès qu''elle bout."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poêlée de Saint-Jacques au whisky', 'poelee de saint jacques au whisky', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poêlée de Saint-Jacques au whisky', 'Noix de Saint-Jacques saisies, flambées au whisky et nappées d''une sauce crème à l''échalote', ds.id, 'SRC-039-D5',
    'Myko', 'editorial', 4, 25, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e4bae007e1fbf8a580730ca832da53dd',
    '{"sweet":2,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['iodé','whisky flambé','crémeux','persil']::text[],
    ARRAY['marin','lacté','céréalier fumé','herbacé']::text[], ARRAY['chair nacrée et moelleuse','sauce nappante par réduction']::text[],
    ARRAY['Noix de Saint-Jacques crue','Whisky','Crème fraîche liquide entière','Vin blanc sec']::text[], ARRAY['Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple poêlée de poisson à la crème.','La chair ne connaît qu''un aller-retour à la poêle et un dernier tour hors du feu dans la sauce : une seconde cuisson franche la rendrait élastique.','Le whisky se flambe et ne se verse pas cru : l''alcool non brûlé domine l''iode et laisse la sauce mordante.','La sauce n''a pas de liant et ne doit pas en recevoir : la rattraper avec un épaississant ferait retomber la variante dans la version gratinée.']::text[],
    ARRAY['saisie','flambage','déglaçage','réduction']::text[], ARRAY[]::text[], ARRAY['mollusques','poisson','lait','sulfites']::text[],
    'Ne se conserve pas : une poêlée se dresse et se mange dans la minute, la chair continuant de cuire dans la sauce chaude tant qu''on la laisse. Ce qui peut s''avancer, c''est la chair parée — 24 h au maximum sur un lit de glace — et rien d''autre. Réchauffage exclu : la noix se rétracte et la sauce, tenue par la seule évaporation, se sépare au second bouillon. Congélation acceptable pour la chair crue étalée à plat et bien épongée (2 mois), exclue pour le plat terminé.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-039'), '{"variant_label":"Poêlée simple flambée à l''alcool de grain, crème et persil, dressée sur riz ou pommes de terre tièdes.","rationale":"Tout le montage du gratin tombe : plus de roux, plus d''appareil aux œufs, plus de chapelure ni de coquille, et la sauce se fait dans la poêle qui a saisi la chair. Le whisky flambé remplace le four comme source de goût grillé et donne un fond céréalier que la version gratinée n''a pas ; en échange on perd la croûte, le contraste de textures et le service en coquille, qui faisait la moitié de l''effet. La crème descend de 300 à 250 g parce que rien ne l''épaissit plus : elle ne tient que par l''évaporation, et il faut lui laisser perdre un bon tiers de son volume. Le plat sort du registre du gratin — il ne se garde pas, il se dresse et se mange dans la minute — et perd du même coup le gluten et l''œuf de ses allergènes.","operations":[{"op":"remove","form":"Farine de blé T55"},{"op":"remove","form":"Œuf cru"},{"op":"remove","form":"Chapelure de blé"},{"op":"add","form":"Whisky","quantity":40,"unit":"ml","role":"alcool de flambage","optional":false},{"op":"set","form":"Crème fraîche liquide entière","quantity":250},{"op":"set","form":"Beurre doux","quantity":10},{"op":"set","form":"Persil plat frais","quantity":15,"optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Rien ici ne se cuit dans le coquillage : le dressage se fait à l''assiette, et les valves peuvent être brossées et rangées pour un autre service ou jetées sans regret."},{"op":"replace","n":3,"instruction":"Chauffer une grande poêle jusqu''à ce qu''elle fume légèrement, y verser l''huile d''olive et saisir la chair bien sèche 45 secondes par face, en deux fois pour ne pas encombrer la poêle. Réunir alors toutes les pièces, retirer la poêle du feu une seconde, verser le whisky, la remettre sur la flamme et l''enflammer en écartant le visage et en éteignant la hotte. Laisser la flamme mourir d''elle-même, puis débarrasser aussitôt la chair sur une assiette froide et garder le jus rendu : elle est encore nacrée à cœur et doit le rester."},{"op":"replace","n":4,"instruction":"Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre, dans la même poêle et sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et gratter les sucs collés au fond, où l''alcool brûlé a laissé sa part la plus intéressante. Laisser réduire à feu moyen jusqu''à un fond sirupeux, environ la moitié du volume."},{"op":"replace","n":5,"instruction":"Verser la crème sur la réduction et la laisser bouillonner doucement six à huit minutes, jusqu''à ce qu''elle nappe le dos d''une cuillère. Rien ne l''épaissira ici qu''elle-même : sans le roux de la version gratinée, elle ne tient que par l''évaporation, et il faut accepter de lui laisser perdre un bon tiers de son volume avant qu''elle prenne du corps. Monter enfin le feu dix secondes si elle reste trop fluide, jamais plus longtemps."},{"op":"replace","n":6,"instruction":"Retirer la poêle du feu, poivrer, ciseler le persil plat dedans et goûter avant de saler : la réduction en apporte déjà beaucoup. Remettre la chair dans la sauce avec le peu de jus qu''elle a encore rendu au repos, la rouler une fois pour l''enrober et la laisser là une minute sans jamais ramener à ébullition — elle finit de cuire dans la chaleur retenue, et c''est la seule cuisson qu''il lui reste à faire."},{"op":"replace","n":7,"instruction":"Dresser sans attendre, sur un lit tiède au fond d''assiettes creuses : un riz long égrené, ou des pommes de terre à l''eau écrasées grossièrement à la fourchette. Poser la chair dessus, napper de sauce et servir. L''accompagnement se choisit au marché et ne compte pas dans la liste : ce qui se pèse ici, c''est la poêlée, le féculent est posé à côté."},{"op":"remove","n":8}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'noix de saint jacques crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Noix de Saint-Jacques crue', 600, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 250, 'g', 'required',
     'sauce', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'vin blanc sec' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Vin blanc sec', 100, 'ml', 'required',
     'déglaçage', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 10, 'g', 'required',
     'matière grasse', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
