  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir à l''achat environ 1,3 kg de bulbes entiers avec leurs tiges et leurs plumets : c''est ce qu''il faut pour arriver aux 900 g de fenouil paré indiqués dans la liste. Sectionner les tiges à ras du bulbe, réserver quelques plumets pour la finition, et supprimer la côte extérieure dès qu''elle paraît fibreuse au toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur, puis recouper en quartiers de deux à trois centimètres d''épaisseur selon la taille du légume, et les citronner aussitôt pour qu''ils ne noircissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive et le beurre ensemble dans une cocotte assez large pour recevoir tous les quartiers sur une seule couche. Y jeter l''oignon finement émincé et le laisser s''attendrir cinq minutes à feu modéré, jusqu''à ce qu''il perde son opacité, sans lui laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer sans y toucher cinq à six minutes. Les retourner pour colorer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le vin blanc sur le fond brûlant et gratter les sucs à la spatule ; laisser bouillonner une minute pour chasser l''alcool. Mouiller ensuite avec le jus de tomate et l''eau mêlés, qui doivent monter à mi-hauteur des quartiers comme dans la version claire : le volume total ne change pas, c''est sa nature qui change. Prélever à l''économe une large lanière de zeste d''orange en restant à la surface de l''écorce, sans emporter le blanc qui amertumerait, et la glisser entre deux morceaux de fenouil. Éparpiller le thym et le sucre, dont l''utilité devient ici plus nette puisque le jus de tomate ajoute son acidité à celle du vin et du citron, puis assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser le couvercle et maintenir un frémissement paresseux pendant quarante minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Compter dix minutes de plus qu''avec de l''eau seule : l''acidité du jus de tomate raffermit les parois des fibres et retarde le moment où elles cèdent. Le fenouil est prêt quand la pointe d''un couteau traverse le cœur sans résistance, et pas une minute avant — sous-cuit dans un liquide acide, il reste franchement croquant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer d''abord la lanière de zeste, qui a donné tout ce qu''elle avait et ne ferait plus que céder son amer. Ôter le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un enrobage rouge et brillant. Rester devant la cocotte à ce moment, cuillère à la main, car la tomate accroche au fond bien plus vite que l''eau et brûle sans prévenir. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre, la sauce cuillérée par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-040-D4', 'recipe_family', 'Fenouil braisé à la provençale',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-040-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
