     jsonb_build_object('recipe_code', 'SRC-040-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-040-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f0f137a7af20c378f3cdb3df3edb2434'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["anisé","tomate cuite","orange","citronné"],"aroma_families":["anisée","agrume","végétal cuit"],"target_textures":["fondant","légèrement confit","jus réduit et nappant"],"signature_ingredients":["Fenouil frais","Jus de tomate","Vin blanc sec"],"identity_guardrails":["Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.","Le jus de tomate reste un mouillement : il se réduit autour des quartiers et les enrobe, il ne les noie pas dans une sauce tomate qui ferait du plat un autre plat.","Le zeste d''orange se retire avant la réduction finale ; laissé dans la cocotte il continue de céder son amertume et couvre l''anis du bulbe.","L''acidité du vin blanc et du citron reste structurante et le jus de tomate s''y ajoute sans la remplacer : privée d''elle, la version provençale vire au légume sucré et l''amertume du bulbe ressort.","La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pommes de terre sarladaises aux cèpes', 'pommes de terre sarladaises aux cepes', 'France', 'France',
     'meal', 'accompagnement', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pommes de terre sarladaises aux cèpes', 'Pommes de terre sarladaises enrichies de cèpes frais rissolés avec l''ail et le persil', ds.id, 'SRC-049-D2',
    'Myko', 'editorial', 4, 35, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '04447f274b45f8ae023183254d17933d',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['ail','canard confit','cèpe rissolé','persil']::text[],
    ARRAY['alliacé','herbacé','gras rôti','sous-bois']::text[], ARRAY['rondelles croustillantes en surface','cœur fondant','cèpes fermes et colorés','chair de canard effilochée']::text[],
    ARRAY['Pomme de terre cuite','Confit de canard cuit','Cèpe cru']::text[], ARRAY['La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.','Les cèpes se rissolent dans une poêle à part et n''arrivent qu''à la fin : versés crus sur les rondelles, ils y rendent leur eau et défont le croustillant.','La cuisson se fait dans un gras de canard ou d''oie, ici celui du confit ; à l''huile, ce sont des pommes de terre sautées ordinaires, plus des sarladaises.','Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée.']::text[],
    ARRAY['saisie','étuvée','hachage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte hermétique. Réchauffage à la poêle bien chaude pour retrouver le croustillant, jamais au micro-ondes. Congélation déconseillée : la pomme de terre déjà cuite rend son eau et devient farineuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-049'), '{"variant_label":"Aux cèpes ou aux girolles : quelques champignons rissolés séparément sont ajoutés en même temps que la persillade, comme le proposent plusieurs pages du dossier.","rationale":"Trois cents grammes de cèpes frais sont rissolés dans une poêle à part et rejoignent les rondelles en même temps que la persillade : le plat gagne un parfum de sous-bois et une seconde mâche, ferme au milieu des pommes de terre fondantes. L''étiquette laisse le choix entre le cèpe et la girolle, et la dérivée tranche pour le cèpe, qui est le champignon du dossier périgourdin ; l''étape de parage dit que la girolle se conduit de la même façon et peut prendre sa place au même poids, mais déclarer les deux ensemble donnerait une pesée que ni l''une ni l''autre des deux versions annoncées ne décrit. Le coût est un quart d''heure de parage à sec avant même d''allumer le feu, et une quatrième cuillerée de gras prélevée sur le confit pour la seconde poêle. C''est aussi un risque : un champignon mal essuyé ou versé cru sur les rondelles rend son eau dans la poêle et défait le croustillant que tout le reste de la méthode cherche à obtenir.","operations":[{"op":"add","form":"Cèpe cru","quantity":300,"unit":"g","role":"légume","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Profitez des dix minutes où les pommes de terre s''attendrissent à couvert pour faire chauffer la quatrième cuillerée de gras dans une seconde poêle, assez large pour recevoir les tranches en une seule couche : entassés, les cèpes s''étuvent au lieu de rissoler. Laissez-les rendre leur eau deux à trois minutes sans y toucher, puis montez le feu et sautez-les cinq à six minutes de plus, jusqu''à ce que le liquide ait entièrement disparu et que les tranches accrochent une couleur noisette. Ne salez qu''à cet instant : le sel donné plus tôt les aurait fait pleurer et les aurait empêchés de colorer."},{"op":"insert","after":2,"instruction":"Nettoyez les cèpes à sec, sans jamais les passer sous le robinet : gorgé d''eau, un champignon ne rissole plus, il bouillonne. Grattez la terre du pied à la pointe du couteau, essuyez les chapeaux au linge à peine humide, puis détaillez pieds et chapeaux en tranches d''un demi-centimètre pour qu''ils cuisent au même rythme. Des girolles rendraient le même service au même poids, à ceci près qu''on se contente de parer leur base, de les garder entières si elles tiennent dans le pouce et de fendre en deux celles qui dépassent. Comptez un bon quart d''heure pour ce travail : c''est lui qui allonge la recette, pas la cuisson."},{"op":"replace","n":3,"instruction":"Prenez une cuisse de confit d''environ 220 g avec son os et son gras, qui donnera les 75 g de chair annoncés. Tiédissez-la à feu doux pour que la graisse se détache, effilochez la viande et réservez-la, en gardant cette fois quatre bonnes cuillerées de gras fondu : trois pour les rondelles, la quatrième mise de côté pour les cèpes, qui doivent rissoler dans le même gras et non dans du beurre."},{"op":"replace","n":7,"instruction":"Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade, la chair de confit effilochée et les cèpes rissolés, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt. Les cèpes arrivent déjà cuits : ils ne font que se mêler aux rondelles, et un séjour plus long leur ferait relâcher dans la poêle l''eau qu''on vient de leur faire perdre."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre cuite' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre cuite', 800, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'confit de canard cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Confit de canard cuit', 75, 'g', 'required',
     'protéine', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 10, 'g', 'required',
     'aromate', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 30, 'g', 'required',
     'herbe', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'cepe cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Cèpe cru', 300, 'g', 'required',
     'légume', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Partez d''environ 1 kg de pommes de terre à chair ferme achetées avec leur peau : une fois pelées et parées, il en reste à peu près les 800 g comestibles de la liste. Détaillez-les en rondelles régulières de 5 mm, ni transparentes ni trop épaisses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincez rapidement les rondelles à l''eau froide pour retirer l''amidon de surface, puis séchez-les longuement dans un linge propre. Une rondelle encore humide s''étuve au lieu de colorer : c''est le point qui décide de la réussite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Nettoyez les cèpes à sec, sans jamais les passer sous le robinet : gorgé d''eau, un champignon ne rissole plus, il bouillonne. Grattez la terre du pied à la pointe du couteau, essuyez les chapeaux au linge à peine humide, puis détaillez pieds et chapeaux en tranches d''un demi-centimètre pour qu''ils cuisent au même rythme. Des girolles rendraient le même service au même poids, à ceci près qu''on se contente de parer leur base, de les garder entières si elles tiennent dans le pouce et de fendre en deux celles qui dépassent. Comptez un bon quart d''heure pour ce travail : c''est lui qui allonge la recette, pas la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Prenez une cuisse de confit d''environ 220 g avec son os et son gras, qui donnera les 75 g de chair annoncés. Tiédissez-la à feu doux pour que la graisse se détache, effilochez la viande et réservez-la, en gardant cette fois quatre bonnes cuillerées de gras fondu : trois pour les rondelles, la quatrième mise de côté pour les cèpes, qui doivent rissoler dans le même gras et non dans du beurre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large, versez-y les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Salez, poivrez, puis faites-les sauter d''un mouvement de poignet toutes les deux minutes pendant une douzaine de minutes, jusqu''à obtenir une coloration dorée assez régulière sur l''ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrez, baissez le feu et laissez le cœur devenir moelleux une dizaine de minutes, en secouant la poêle de temps à autre. Évitez la cuillère à ce stade, elle écraserait les rondelles ramollies.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Profitez des dix minutes où les pommes de terre s''attendrissent à couvert pour faire chauffer la quatrième cuillerée de gras dans une seconde poêle, assez large pour recevoir les tranches en une seule couche : entassés, les cèpes s''étuvent au lieu de rissoler. Laissez-les rendre leur eau deux à trois minutes sans y toucher, puis montez le feu et sautez-les cinq à six minutes de plus, jusqu''à ce que le liquide ait entièrement disparu et que les tranches accrochent une couleur noisette. Ne salez qu''à cet instant : le sel donné plus tôt les aurait fait pleurer et les aurait empêchés de colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade, la chair de confit effilochée et les cèpes rissolés, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt. Les cèpes arrivent déjà cuits : ils ne font que se mêler aux rondelles, et un séjour plus long leur ferait relâcher dans la poêle l''eau qu''on vient de leur faire perdre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-049-D2', 'recipe_family', 'Pommes de terre sarladaises aux cèpes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-049-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-049-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-049-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('04447f274b45f8ae023183254d17933d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["ail","canard confit","cèpe rissolé","persil"],"aroma_families":["alliacé","herbacé","gras rôti","sous-bois"],"target_textures":["rondelles croustillantes en surface","cœur fondant","cèpes fermes et colorés","chair de canard effilochée"],"signature_ingredients":["Pomme de terre cuite","Confit de canard cuit","Cèpe cru"],"identity_guardrails":["La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.","Les cèpes se rissolent dans une poêle à part et n''arrivent qu''à la fin : versés crus sur les rondelles, ils y rendent leur eau et défont le croustillant.","La cuisson se fait dans un gras de canard ou d''oie, ici celui du confit ; à l''huile, ce sont des pommes de terre sautées ordinaires, plus des sarladaises.","Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
