  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Monter la vinaigrette en premier pour qu''elle attende au frais : délayer la moutarde de Dijon dans le vinaigre de vin rouge avec le sel fin, puis incorporer 90 g d''huile d''olive en mince filet au fouet jusqu''à ce que le mélange épaississe et cesse de se séparer. Poivrer et réserver ; les 30 g d''huile restants serviront au pain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser les lardons fumés dans une poêle froide sans aucune matière grasse, monter à feu moyen et les laisser rendre leur gras puis colorer une petite dizaine de minutes en remuant de temps en temps. Les débarrasser sur du papier absorbant et jeter la graisse de la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Compter environ 130 g de noix en coquille chez le primeur pour obtenir les 55 g de cerneaux utiles ici — la coque part à la poubelle et représente plus de la moitié du poids acheté. Casser, trier, puis concasser les cerneaux au couteau en gros éclats irréguliers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Rincer les tomates cerises à l''eau froide, ôter les pédoncules et les couper en deux dans le sens de la hauteur plutôt que par l''équateur : fendues ainsi, elles gardent leurs loges et ne se vident pas de leur jus dans le saladier. Les laisser à température ambiante en attendant le dressage, une tomate sortie du froid n''a presque pas de goût.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mettre le gril du four en chauffe à 220 °C avec une plaque garnie de papier cuisson. Trancher le pain de campagne en quatre larges tranches d''environ 50 g et un doigt d''épaisseur, puis les badigeonner d''huile d''olive sur la face qui recevra le fromage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ôter les deux extrémités croûtées de la bûche de chèvre et la débiter en quatre rondelles d''environ 25 g. En coiffer chaque tranche de pain, déposer un filet de miel sur le fromage et pincer les herbes de Provence entre les doigts au-dessus des toasts pour les réveiller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Glisser la plaque sous le gril à mi-hauteur et surveiller sans s''éloigner : cinq à huit minutes suffisent pour que le chèvre s''affaisse, blondisse par endroits et laisse apparaître de petites bulles en surface. Le pain doit rester ferme dessous, jamais desséché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Pendant le gratinage, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer les demi-tomates cerises face coupée vers le haut, les lardons égouttés et les éclats de noix. Napper de vinaigrette au dernier moment en visant les feuilles plutôt que les tomates, qui ne retiennent rien, puis poser un toast brûlant sur chaque assiette et servir sans attendre pour garder le contraste chaud-froid.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
