  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. On part de deux cuisses confites telles qu''on les achète, environ 180 g pièce avec l''os et leur couche de graisse : elles rendront les 200 g de chair comestible portés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher les cuisses peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que les cuisses se manipulent, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un autre bol, délayer la moutarde avec le vinaigre, une pincée de sel et un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir le foie gras du froid au dernier moment et le trancher en quatre escalopes d''un bon centimètre, la lame passée sous l''eau chaude et essuyée entre chaque coupe pour qu''elle glisse au lieu d''écraser. Chauffer une poêle à sec jusqu''à ce qu''elle commence à peine à fumer, assaisonner les escalopes des deux côtés d''une pincée prise sur le sel restant et d''un tour de moulin, puis les saisir trente à quarante secondes par face : le dessus doit être coloré et le centre encore crémeux. Les débarrasser aussitôt sur du papier absorbant — laissées dans la poêle, elles continuent de fondre et il ne reste qu''une flaque de graisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Étaler la pulpe de tomate au fond de chaque assiette, disposer la chair de canard tiède et les éclats de peau en couronne autour d''un creux laissé libre, napper d''un filet de vinaigrette, puis poser l''escalope de foie gras brûlante dans ce creux au tout dernier geste. Porter à table sans attendre : le foie gras poêlé continue de rendre son gras dans l''assiette et fige dès qu''il refroidit, et c''est la seule pièce du plat qu''on ne peut pas servir tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D4', 'recipe_family', 'Salade landaise au foie gras',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a100c92919a8ac81585985687a1c3cc5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":4},"dominant_flavors":["foie gras poêlé","gras de canard confit","acidité vinaigrée","moutarde"],"aroma_families":["rôti","abats","acidulé"],"target_textures":["foie gras crémeux et tiède","peau de canard croustillante","chair effilochée fondante","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Foie gras de canard cru","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le foie gras se pose sur le confit, il ne le remplace pas.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du foie gras ; une sauce crémée efface l''identité gasconne.","L''escalope se saisit à sec, poêle très chaude et moins d''une minute par face : cuite plus longtemps ou lancée dans une matière grasse ajoutée, elle fond et il ne reste rien à poser au centre.","Le foie gras arrive brûlant sur une base froide et se sert dans la minute : refroidi, il fige et graisse le fond de l''assiette."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise à la truite fumée', 'salade landaise a la truite fumee', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise à la truite fumée', 'Salade avec confit de canard et filet de truite fumée en vinaigrette moutardée', ds.id, 'SRC-054-D5',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e03523eec7cb4dcba1de7317bcb5f698',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','truite fumée','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','fumée','marine']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','lanières de truite souples et froides','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Truite fumée','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Le canard confit reste dans l''assiette, en quantité réduite mais présent : la truite en remplace une partie, jamais la totalité, sans quoi le plat n''a plus rien de landais.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de tenir ensemble un gras tiède et un poisson fumé ; une sauce crémée efface l''identité gasconne.','La truite se sert froide et telle quelle, en lanières taillées au dernier moment : passée à la poêle ou seulement tiédie, elle s''effrite et perd le fumé qui la justifie.','Le canard se pose tiède, la truite froide, sur une base non assaisonnée à l''avance : tout mettre à la même température transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites','poisson']::text[],
    'À manger dans la foulée du dressage. La truite fumée sous vide se garde jusqu''à sa date, mais deux jours seulement une fois le sachet ouvert, et elle se détaille au dernier moment : les lanières coupées à l''avance sèchent et se collent entre elles. Les autres éléments se gardent séparément : chair de canard désossée trois jours à 4 °C sous sa graisse, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Ne se congèle pas : la tomate râpée rend son eau, la peau de canard ramollit, et une truite déjà fumée devient farineuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Variante landaise à la truite fumée, détaillée en lanières, en remplacement d''une partie du canard.","rationale":"Le confit descend de deux cuisses à une seule, cent vingt grammes de chair au lieu de deux cents, et cent cinquante grammes de truite fumée viennent occuper la place — plus large, en vérité, que celle qui vient d''être libérée : l''assiette passe de deux cents à deux cent soixante-dix grammes de protéine, soit soixante-sept grammes par personne, et bascule de l''entrée vers la salade de repas. Elle garde son ossature gasconne — la peau croustillante, le gras tiède, la vinaigrette moutardée — mais l''oppose désormais à un poisson froid, salé et fumé au lieu de la doubler. Ce qui recule est la sensation de graisse fondue, non la graisse elle-même : la truite fumée porte moins de la moitié des lipides d''une chair de confit aux cent grammes, mais comme il en entre presque deux fois plus qu''il n''est sorti de canard, le gras de l''assiette perd moins d''un dixième et l''énergie ne recule pas du tout — elle monte même de quelques kilocalories par part. Le vrai coût est ailleurs : un allergène de plus, le poisson, dans une recette qui n''en portait aucun ; un sel qui passe d''environ un gramme et demi à près de deux grammes et demi par part, la truite fumée en portant trois aux cent grammes ; et une contrainte de dressage — la truite doit rester froide et se détailler au dernier moment, sans quoi ses lanières sèchent et se collent entre elles.","operations":[{"op":"set","form":"Confit de canard cuit","quantity":120,"role":"protéine"},{"op":"add","form":"Truite fumée","quantity":150,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. Ici une seule cuisse suffit, la plus grosse du bocal, environ 220 g avec l''os et sa couche de graisse : elle rendra les 120 g de chair comestible portés dans la liste, la truite fumée tenant le reste de l''assiette."},{"op":"replace","n":2,"instruction":"Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher la cuisse peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture. Une seule pièce dans une grande poêle colore mieux qu''un fond encombré, il n''y a donc pas lieu de prendre plus petit."},{"op":"replace","n":4,"instruction":"Dès que la cuisse se manipule, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud."},{"op":"insert","after":4,"instruction":"Détailler la truite fumée en lanières d''un bon centimètre, en suivant le sens des feuillets plutôt qu''en travers : coupée à contresens, elle se casse en miettes qui disparaîtront dans la salade. La garder au réfrigérateur jusqu''au dressage et à l''écart de la poêle — un poisson fumé posé dans la chaleur perd son gras et sa fermeté en quelques minutes."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, puis entrelacer les lanières de truite fumée sorties du froid, sans les poser sur la viande chaude. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le contraste s''efface en quelques minutes, et il joue ici entre le gras tiède du canard et le fumé froid du poisson."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'confit de canard cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Confit de canard cuit', 120, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
