  VALUES (v_version, 1, 'Faire suer finement oignon, carotte et céleri. Ajouter le bœuf haché en deux fois et l''émietter à la cuillère jusqu''à légère coloration sans excès.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
