     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'IT-001-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-001-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b1745d4fadb048c9f7132bf3078cd05e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5},"dominant_flavors":["umami","rôti","vinique"],"aroma_families":["oignon_compoté","vin_rouge_réduit","tomate_cuite","beurre","parmesan"],"target_textures":["protéine_fondante","sauce_nappante"],"signature_ingredients":["Feuille de lasagne sèche","Bœuf haché cru 15 % MG","Tomate concassée en conserve"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lasagnes courgettes et lentilles', 'lasagnes courgettes et lentilles', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes au four', 'documented_variation', 'rich_winey',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Lasagnes courgettes et lentilles', 'Couches de pâtes alternées avec un ragù de courgettes et lentilles vertes et une béchamel à la muscade, gratinées au parmesan', ds.id, 'IT-001-D3',
    'Myko', 'editorial', 8, 50, 150, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'fa4e96374719783d7f878a5de26a0411',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5}'::jsonb, ARRAY['umami','rôti','vinique']::text[],
    ARRAY['oignon_compoté','vin_rouge_réduit','tomate_cuite','beurre','parmesan']::text[], ARRAY['protéine_fondante','sauce_nappante']::text[],
    ARRAY['Feuille de lasagne sèche','Tomate concassée en conserve']::text[], ARRAY['conserver_les_ingrédients_signatures','conserver_la_technique_centrale','ne_pas_remplacer_par_un_simple_équivalent_nutritionnel']::text[],
    ARRAY['soffritto','saisie','déglaçage','mijotage','roux','montage','gratinage']::text[], ARRAY[]::text[], ARRAY['céleri','gluten','lait']::text[],
    '4 jours au réfrigérateur ; congélation 3 mois.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-001'), '{"variant_label":"courgettes-lentilles","rationale":"Les courgettes en dés et les lentilles vertes remplacent la viande en apportant des textures différentes : la lentille lie le ragù comme le faisait le bœuf, la courgette l''aère. La béchamel et le parmesan restent — c''est le seul liant qui tienne le montage sans viande. La durée de mijotage tombe à trente minutes, les lentilles cuisant nettement plus vite que la viande hachée.","operations":[{"op":"remove","form":"Bœuf haché cru 15 % MG"},{"op":"remove","form":"Porc haché cru"},{"op":"add","form":"Courgette fraîche","quantity":500,"unit":"g","role":"légume"},{"op":"add","form":"Lentille verte sèche, crue","quantity":200,"unit":"g","role":"protéine végétale"}],"steps":[{"op":"replace","n":1,"instruction":"Faire suer finement oignon, carotte et céleri. Ajouter les courgettes taillées en dés de cinq millimètres et les laisser revenir deux minutes à feu vif jusqu''à légère coloration."},{"op":"replace","n":2,"instruction":"Déglacer au vin rouge, laisser réduire, ajouter les lentilles vertes rincées, la tomate concassée et 150 ml de lait. Couvrir et mijoter trente minutes à feu doux, jusqu''à ce que les lentilles soient tendres et la sauce liée."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
