  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher oignon, carotte et céleri, puis les tailler en dés de deux à trois millimètres. Le soffritto n''a pas à se retrouver sous la dent : son travail est de fondre dans la sauce et d''en faire le fond sucré. Taillé gros, il reste croquant après une heure de feu et le plat garde un goût de légumes ajoutés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une sauteuse large, y verser les légumes et les laisser suer dix à douze minutes à feu moyen, en remuant. Les saler d''une pincée dès le début : le sel tire l''eau des légumes et les fait fondre au lieu de les colorer. Ils doivent devenir translucides et l''oignon à peine blond, sans jamais roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pousser le feu, ajouter le bœuf haché en deux fois et l''écraser à la cuillère de bois pour le détacher. Une viande versée d''un seul coup rend son eau, bouillit dans son jus et ressort grise — c''est cet écueil qu''on évite en procédant en deux fois : c''est la coloration brune, pas grise, qui fait toute la profondeur de la sauce. Attendre que le fond de la sauteuse crépite avant de remuer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le vin rouge dans la sauteuse et gratter immédiatement les sucs caramélisés du fond à la cuillère de bois. Laisser réduire à feu vif jusqu''à presque complète évaporation — une à deux minutes suffit, et l''alcool part avant la fumée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le concentré de tomate et le remuer une bonne minute au contact du fond chaud, le temps qu''il perde son goût métallique de crudité et qu''il fonce. Puis verser la tomate concassée, l''ail écrasé, le thym et le laurier. Rincer la boîte avec un fond d''eau et le verser aussi — c''est de la sauce qui resterait collée au métal.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser mijoter quarante-cinq minutes à découvert, à petits bouillons, en raclant le fond toutes les dix minutes. La sauce est prête quand elle ne coule plus de la cuillère et que la graisse remonte en brillant à la surface. Goûter alors : si l''acidité de la tomate reste piquante, une pincée de sucre l''arrondit mieux qu''un ajout de gras.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Porter à ébullition un grand volume d''eau — comptez un litre et dix grammes de sel pour cent grammes de pâtes — et y cuire les spaghetti. Les égoutter une minute avant le temps du paquet, en réservant une louche d''eau de cuisson. Ne jamais les rincer ni les huiler : l''amidon de surface est ce qui fera tenir la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer thym et laurier, verser les pâtes dans la sauteuse avec une petite louche d''eau de cuisson et remuer une minute sur le feu. L''amidon lie la sauce aux pâtes et l''enrobe au lieu de la laisser au fond de l''assiette. Servir aussitôt, le parmesan râpé à part pour ceux qui en veulent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'IT-004-D1', 'recipe_family', 'Spaghetti bolognaise au vin rouge',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'IT-004-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'IT-004-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-004-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6735090e53e257aa2f3f0925b9d178d5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["tomate cuite","viande rissolée","légume compoté"],"aroma_families":["tomate_cuite","oignon_compoté","viande_rissolée","thym"],"target_textures":["sauce_nappante","pâtes_fermes","haché_fondant"],"signature_ingredients":["Spaghetti secs","Bœuf haché cru 15 % MG","Tomate concassée en conserve","Carotte crue","Céleri branche cru"],"identity_guardrails":["Sans le trio oignon-carotte-céleri fondu au départ, il reste une sauce tomate à la viande : c''est le soffritto qui donne au plat son sucre et son corps, et cinq à six sources sur huit le portent.","La viande hachée doit rissoler avant d''être mouillée ; pochée directement dans la tomate, elle ne développe rien et la sauce reste plate quelle que soit la durée du mijotage.","La tomate doit être une base longuement réduite, pas un concentré délayé : deux sources font l''inverse et produisent une autre sauce, épaisse et sucrée, qui ne mijote pas.","Les pâtes se terminent dans la sauce avec un peu de leur eau de cuisson ; servies nues avec la sauce posée dessus, le plat se dissocie dans l''assiette."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Spaghetti bolognaise aux champignons', 'spaghetti bolognaise aux champignons', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes en sauce', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Spaghetti bolognaise aux champignons', 'Spaghetti nappés d''un ragù de bœuf haché et champignons de Paris émincés au soffritto, mijotés à la tomate', ds.id, 'IT-004-D2',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '595f38cf24f7373f2c32d00fec5c834b',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate cuite','viande rissolée','légume compoté']::text[],
    ARRAY['tomate_cuite','oignon_compoté','viande_rissolée','thym']::text[], ARRAY['sauce_nappante','pâtes_fermes','haché_fondant']::text[],
    ARRAY['Spaghetti secs','Bœuf haché cru 15 % MG','Tomate concassée en conserve','Carotte crue','Céleri branche cru']::text[], ARRAY['Sans le trio oignon-carotte-céleri fondu au départ, il reste une sauce tomate à la viande : c''est le soffritto qui donne au plat son sucre et son corps, et cinq à six sources sur huit le portent.','La viande hachée doit rissoler avant d''être mouillée ; pochée directement dans la tomate, elle ne développe rien et la sauce reste plate quelle que soit la durée du mijotage.','La tomate doit être une base longuement réduite, pas un concentré délayé : deux sources font l''inverse et produisent une autre sauce, épaisse et sucrée, qui ne mijote pas.','Les pâtes se terminent dans la sauce avec un peu de leur eau de cuisson ; servies nues avec la sauce posée dessus, le plat se dissocie dans l''assiette.']::text[],
    ARRAY['soffritto','saisie du haché','cuisson du concentré','mijotage','cuisson al dente','enrobage à l''eau de cuisson']::text[], ARRAY[]::text[], ARRAY['gluten','céleri','lait']::text[],
    'La sauce se garde quatre jours au réfrigérateur dans un récipient fermé et gagne à être faite la veille : la tomate finit de perdre son acidité au froid. Elle se congèle trois mois, sans les pâtes. Réchauffer à feu doux avec une cuillerée d''eau. Les pâtes déjà enrobées ne se conservent pas plus de vingt-quatre heures et ne se congèlent pas : elles rendent leur eau et deviennent farineuses.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-004'), '{"variant_label":"Champignons de Paris émincés avec le soffritto (deux sources)","rationale":"Les champignons de Paris ajoutés au soffritto apportent de l''umami sans alourdir la sauce, et fondent en rendant leur eau, ce qui raccourcit la prise de la tomate. Attesté par deux sources sur huit, c''est une variation courante en cuisine domestique.","operations":[{"op":"add","form":"Champignon de Paris frais","quantity":250,"unit":"g","role":"soffritto"}],"steps":[{"op":"replace","n":1,"instruction":"Éplucher oignon, carotte et céleri, puis les tailler en dés de deux à trois millimètres. Émincer finement les champignons de Paris — pas trop petits, ils fondent à la cuisson et disparaîtraient s''ils étaient hachés fin. Le soffritto n''a pas à se retrouver sous la dent : son travail est de fondre dans la sauce et d''en faire le fond sucré et umami."},{"op":"replace","n":2,"instruction":"Faire chauffer l''huile d''olive dans une sauteuse large, y verser les légumes du soffritto et les champignons émincés, et les laisser suer douze à quinze minutes à feu moyen, en remuant. Les saler d''une pincée dès le début : le sel tire l''eau des légumes et des champignons et les fait fondre au lieu de les colorer. Ils doivent devenir translucides, l''oignon à peine blond, sans jamais roussir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'spaghetti secs' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Spaghetti secs', 600, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'boeuf hache cru 15 mg' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bœuf haché cru 15 % MG', 450, 'g', 'required',
     'protéine', false, 2);

