      WHERE ff.canonical_name_normalized = 'bouillon de volaille' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de volaille', 2000, 'ml', 'required',
     'mouillement', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
