  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préparer les haricots blancs la veille si on part du sec : deux cents grammes secs, trempés une nuit puis cuits cinquante à soixante minutes dans une eau non salée, donnent les quatre cent cinquante grammes annoncés — le poids déclaré est celui du haricot cuit et égoutté, pas celui du sachet. En boîte, rincer et égoutter : le poids compté est celui du contenu sorti de la conserve, saumure exclue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler carotte, céleri, oignon et pomme de terre en dés d''un centimètre, tous de la même taille. Un minestrone se juge à la cuillère : des dés réguliers cuisent ensemble et se prennent ensemble. Mettre à part la courgette, taillée pareil, et les haricots verts coupés en tronçons de deux centimètres — ces deux-là entreront bien plus tard.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Si l''on met du lard, le faire rendre à sec dans une grande cocotte à feu moyen jusqu''à ce qu''il croustille, puis ajouter l''huile d''olive. Sinon, chauffer l''huile seule. Verser oignon, carotte, céleri et ail écrasé et les laisser suer dix minutes sans coloration, à couvert et à feu doux : on cherche à ouvrir les légumes, pas à les rôtir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les pommes de terre en dés et les tomates entières pelées égouttées sommairement, en les écrasant grossièrement à la cuillère directement dans la cocotte pour les défaire sans les mixer. Laisser cinq minutes à découvert à feu moyen pour réduire l''acidité avant de mouiller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon, porter à frémissement puis baisser le feu et laisser cuire vingt-cinq minutes à couvert. Le bouillon doit à peine trembler : une ébullition franche défait les dés et trouble la soupe, qui doit rester une soupe de légumes reconnaissables et non une purée claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la courgette, les haricots verts et les haricots blancs cuits, et poursuivre dix minutes. La courgette mise au départ aurait fondu sans laisser de trace, et les haricots blancs déjà cuits n''ont besoin que de se réchauffer et de prendre le goût du bouillon — les faire mijoter plus longtemps leur ferait perdre leur peau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser les petites pâtes directement dans la soupe et les cuire deux minutes de moins que le temps du paquet, en goûtant. C''est leur amidon qui donne au minestrone son épaisseur, et c''est pour cela qu''on ne les cuit pas à part. Mais elles continuent de boire après l''arrêt du feu : les laisser tout juste fermes, sinon la soupe sera un plat de pâtes le lendemain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer du feu, déchirer le basilic dedans et ajouter un filet d''huile d''olive crue. Goûter et saler seulement maintenant : le bouillon, le lard s''il y en a et le parmesan du service apportent déjà beaucoup de sel, et une soupe salée en début de cuisson devient impossible à corriger après réduction. Servir avec le parmesan râpé à part.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'IT-008-D1', 'recipe_family', 'Minestrone aux tomates pelées en conserve',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'IT-008-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'IT-008-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-008-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('05f2c242735a608b76e2cfa7057715d1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["bouillon de légumes","tomate","basilic"],"aroma_families":["bouillon","tomate_cuite","oignon_compoté","basilic","céleri"],"target_textures":["légumes_tendres_distincts","bouillon_lié","pâtes_fermes"],"signature_ingredients":["Haricot blanc cuit, égoutté","Petites pâtes sèches","Tomate entière pelée en conserve","Courgette fraîche","Basilic frais"],"identity_guardrails":["Un minestrone porte à la fois une légumineuse et un féculent en grain — haricot blanc et petites pâtes ici : sans eux, il reste une soupe de légumes, et six sources sur huit portent l''un ou l''autre.","Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom.","Les légumes entrent par ordre de tenue, les durs d''abord et les tendres dix minutes avant la fin ; tous ensemble, la courgette disparaît et la carotte reste crue.","Les pâtes cuisent dans le bouillon et non à part : leur amidon est le seul liant de la soupe, et cuites séparément elles laissent un bouillon clair."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Minestrone aux poireaux', 'minestrone aux poireaux', 'Italie', 'Italie',
     'meal', 'soupe complète', 'documented_variation', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Minestrone aux poireaux', 'Soupe épaisse de légumes de saison et légumineuses au bouillon de volaille, avec poireaux émincés fondus dans le soffritto', ds.id, 'IT-008-D2',
    'Myko', 'editorial', 8, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', '3bb861081bee420a4dff5e8e3da486dc',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['bouillon de légumes','tomate','basilic']::text[],
    ARRAY['bouillon','tomate_cuite','oignon_compoté','basilic','céleri']::text[], ARRAY['légumes_tendres_distincts','bouillon_lié','pâtes_fermes']::text[],
    ARRAY['Haricot blanc cuit, égoutté','Petites pâtes sèches','Tomate fraîche mûre','Courgette fraîche','Basilic frais']::text[], ARRAY['Un minestrone porte à la fois une légumineuse et un féculent en grain — haricot blanc et petites pâtes ici : sans eux, il reste une soupe de légumes, et six sources sur huit portent l''un ou l''autre.','Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom.','Les légumes entrent par ordre de tenue, les durs d''abord et les tendres dix minutes avant la fin ; tous ensemble, la courgette disparaît et la carotte reste crue.','Les pâtes cuisent dans le bouillon et non à part : leur amidon est le seul liant de la soupe, et cuites séparément elles laissent un bouillon clair.']::text[],
    ARRAY['suer','cuisson séquencée par tenue des légumes','cuisson des pâtes dans le bouillon','finition à l''huile crue']::text[], ARRAY[]::text[], ARRAY['gluten','céleri','lait']::text[],
    'Quatre jours au réfrigérateur, et la soupe gagne du goût la deuxième journée. Réserve faite des pâtes : elles continuent d''absorber le bouillon au froid et la soupe se resserre en plat épais — allonger d''un demi-litre de bouillon au réchauffage, ou cuire les pâtes le jour même dans la portion qu''on va servir et garder le reste sans elles. Se congèle trois mois, sans les pâtes ni la pomme de terre, qui se délitent à la décongélation. Réchauffer à frémissement et ajouter le basilic seulement au moment de servir.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-008'), '{"variant_label":"Deux poireaux émincés ou un blanc de poireau ajoutés au soffritto (deux sources)","rationale":"Le poireau fondu apporte une douceur végétale qui répond bien au bouillon de volaille et à la tomate — il s''intègre dans le soffritto sans l''alourdir, contrairement à l''oignon supplémentaire qui aurait le même effet sucrant mais une présence plus piquante.","operations":[{"op":"add","form":"Poireau cru","quantity":300,"unit":"g","role":"aromatique"}],"steps":[{"op":"replace","n":2,"instruction":"Tailler carotte, céleri, oignon et pomme de terre en dés d''un centimètre, tous de la même taille. Fendre les poireaux dans la longueur, les rincer abondamment sous l''eau pour ôter le sable et les émincer en rondelles de trois millimètres. Mettre à part la courgette, taillée pareil, et les haricots verts coupés en tronçons de deux centimètres."},{"op":"replace","n":3,"instruction":"Si l''on met du lard, le faire rendre à sec dans une grande cocotte à feu moyen jusqu''à ce qu''il croustille, puis ajouter l''huile d''olive. Sinon, chauffer l''huile seule. Verser oignon, carotte, céleri, poireaux et ail écrasé et les laisser suer dix minutes sans coloration, à couvert et à feu doux : on cherche à ouvrir les légumes, pas à les rôtir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de volaille' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de volaille', 2000, 'ml', 'required',
     'mouillement', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
