  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons, hacher l''ail, épépiner les poivrons et les tailler en morceaux d''environ deux centimètres. Éplucher la carotte et la tailler en petits dés d''un demi-centimètre, de la même taille que l''oignon pour qu''elle cuise et fonde avec lui. Égoutter les haricots rouges dans une passoire et les rincer à l''eau froide jusqu''à ce qu''elle cesse de mousser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié de l''huile dans une cocotte à fond épais et y colorer le bœuf haché en deux ou trois fois, en couche mince, sans remuer pendant la première minute. Une seule fournée refroidirait le fond, la viande rendrait son eau et bouillirait au lieu de brunir — or c''est cette croûte brune qui donne au chili sa profondeur. Débarrasser la viande colorée dans un plat au fur et à mesure, en gardant les sucs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le reste d''huile dans la cocotte et y faire fondre les oignons et la carotte huit minutes à feu moyen, en grattant le fond avec la cuillère pour dissoudre les sucs de la viande. Ajouter les poivrons et poursuivre cinq minutes, le temps qu''ils perdent leur cru sans se défaire, puis l''ail haché pour une minute seulement — au-delà il brûle et devient amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baisser le feu et jeter d''un coup le paprika doux, le piment en poudre, le cumin, l''origan et le Cayenne sur les légumes. Remuer trente à quarante secondes, pas plus : la chaleur et le gras réveillent les huiles essentielles des épices et changent leur odeur, qui passe du poussiéreux au grillé. Guetter ce virage et mouiller aussitôt — une épice brûlée ne se rattrape pas, elle amertume le plat entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre la viande et ses sucs, verser les tomates concassées et le bouillon, poivrer et porter à petite ébullition. Baisser à frémissement, couvrir à demi et laisser mijoter quarante minutes en remuant de temps en temps pour que rien n''attache. La sauce doit réduire lentement et napper la cuillère ; si elle épaissit trop tôt, ajouter un fond d''eau chaude plutôt que de couvrir complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les haricots rincés et poursuivre vingt minutes à découvert. Ils entrent tard exprès : une heure de mijotage les ferait éclater et leur peau se détacherait dans la sauce, alors que vingt minutes suffisent à les charger d''épices en les laissant entiers sous la dent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ne saler qu''ici, en fin de cuisson, et par petites pincées en goûtant : le bouillon a déjà salé le plat et la réduction a concentré ce qu''il apportait — les 6 g prévus sont un plafond, pas une consigne. Rectifier la chaleur au Cayenne si le chili est trop sage, l''acidité en prolongeant le mijotage de cinq minutes si les tomates piquent encore, et la texture en poussant deux minutes à feu vif si la sauce reste liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Laisser reposer un quart d''heure hors du feu avant de servir, ou mieux, préparer le chili la veille : les épices continuent de se diffuser à froid et le plat réchauffé est nettement plus rond que le plat sorti de la cocotte. Servir sur du riz long, avec des tortillas ou du pain, dans des assiettes creuses.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'MX-001-D1', 'recipe_family', 'Chili con carne à la carotte',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'MX-001-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'MX-001-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:MX-001-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a5a0d5ab79d6f6ea3dabbb912d5b0926'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":4,"pungency":3,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["piment","cumin","tomate cuite","bœuf bruni"],"aroma_families":["épices torréfiées","oignon compoté","tomate mijotée","paprika"],"target_textures":["haché fondant","haricot entier sous la dent","sauce nappante","poivron tendre"],"signature_ingredients":["Bœuf haché cru 15 % MG","Haricot rouge cuit, égoutté","Piment en poudre"],"identity_guardrails":["Du piment en quantité perceptible : sans chaleur, ce n''est qu''une sauce à la viande","Le haricot rouge, que les neuf sources du dossier portent sans exception","Du bœuf haché brièvement bruni avant le mouillement, jamais bouilli d''entrée","Cumin et origan : c''est ce couple qui sort le plat du registre de la bolognaise"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chili con carne gratiné', 'chili con carne gratine', 'Tex-Mex, adapté en cuisine domestique française', 'Tex-Mex, adapté en cuisine domestique française',
     'meal', 'plat mijoté', 'documented_variation', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Chili con carne gratiné', 'Bœuf haché mijoté aux haricots rouges, tomate et poivron dans un bouillon épicé, gratiné sous un mélange emmental-chapelure', ds.id, 'MX-001-D2',
    'Myko', 'editorial', 6, 20, 80, 'facile',
    NULL, NULL,
    'B', 'candidate', '64894b97955ba218b953495cc71abe6e',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":4,"pungency":3,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['piment','cumin','tomate cuite','bœuf bruni']::text[],
    ARRAY['épices torréfiées','oignon compoté','tomate mijotée','paprika']::text[], ARRAY['haché fondant','haricot entier sous la dent','sauce nappante','poivron tendre']::text[],
    ARRAY['Bœuf haché cru 15 % MG','Haricot rouge cuit, égoutté','Piment en poudre']::text[], ARRAY['Du piment en quantité perceptible : sans chaleur, ce n''est qu''une sauce à la viande','Le haricot rouge, que les neuf sources du dossier portent sans exception','Du bœuf haché brièvement bruni avant le mouillement, jamais bouilli d''entrée','Cumin et origan : c''est ce couple qui sort le plat du registre de la bolognaise']::text[],
    ARRAY['saisie en plusieurs fournées','déglaçage des sucs','fondue d''oignons et de poivrons','torréfaction des épices','mijotage à couvert partiel','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 4 jours au réfrigérateur dans un contenant fermé et gagne au repos : les épices se diffusent encore à froid. Se congèle 3 mois en portions, sans le riz ; décongeler une nuit au réfrigérateur puis réchauffer à couvert à feu doux avec deux cuillerées d''eau, la sauce ayant épaissi au froid. Ne pas réchauffer plus d''une fois.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'MX-001'), '{"variant_label":"Gratiné au four : emmental râpé et chapelure sur le dessus en fin de cuisson (chefsimon)","rationale":"Le gratin transforme un plat mijoté en plat de four : la croûte d''emmental et de chapelure capte la chaleur du gril et forme une couche dorée et croustillante qui contraste avec le chili fondant dessous. Attesté par une source (chefsimon).","operations":[{"op":"add","form":"Emmental râpé","quantity":100,"unit":"g","role":"gratinage"},{"op":"add","form":"Chapelure de blé","quantity":30,"unit":"g","role":"gratinage"}],"steps":[{"op":"replace","n":8,"instruction":"Laisser reposer un quart d''heure hors du feu, puis verser le chili dans un plat à gratin ou dans des ramequins individuels. Mélanger la chapelure et l''emmental râpé et en parsemer uniformément le dessus. Passer cinq à huit minutes sous le gril préchauffé, en surveillant, jusqu''à belle coloration dorée. Servir immédiatement."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
